        self.attach_tree.heading("tipo", text="Tipo")
        self.attach_tree.heading("percorso", text="Percorso")
        self.attach_tree.column("nome", width=260)
        self.attach_tree.column("tipo", width=100, anchor="center")
        self.attach_tree.column("percorso", width=520)
