class ScoringPlusWindow(BaseWindow):
    """Modulo integrato per input dati strutturato e scoring PMI."""

    SP_FIELDS = [
        "Liquidità", "Crediti", "Magazzino", "Immobilizzazioni",
        "Debiti bancari", "Debiti fornitori", "Altri debiti", "Patrimonio netto",
    ]
    CE_FIELDS = ["Ricavi", "EBITDA", "EBIT", "Utile netto", "Oneri finanziari"]
    YEARS = ["Anno -2", "Anno -1", "Attuale"]
    MONTHS_36 = [f"Mese {i:02d}" for i in range(1, 37)]
    MONTHS_12 = [f"Mese {i:02d}" for i in range(1, 13)]

    def __init__(self, master, db: Database):
        super().__init__(master, "Scoring Plus", "1250x760")
        self.db = db
        self.current_client_id = None
        self.clients_cache = []
        self.inputs = {}
        self._ensure_tables()
        self._build_ui()
        self._load_clients()

    def _ensure_tables(self):
        self.db.conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS scoring_plus_inputs (
                client_id INTEGER PRIMARY KEY,
                data_json TEXT NOT NULL,
                updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE
            );
            CREATE TABLE IF NOT EXISTS scoring_plus_documents (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                client_id INTEGER NOT NULL,
                category TEXT,
                original_filename TEXT,
                stored_path TEXT,
                notes TEXT,
                uploaded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE
            );
            CREATE TABLE IF NOT EXISTS scoring_plus_reports (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                client_id INTEGER NOT NULL,
                report_path TEXT NOT NULL,
                summary_json TEXT,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE
            );
            """
        )
        self.db.conn.commit()

    def _build_ui(self):
        root = ttk.Frame(self.content_frame, padding=16)
        root.pack(fill="both", expand=True)

        top = ttk.Frame(root)
        top.pack(fill="x", pady=(0, 12))
        ttk.Label(top, text="Cliente:", font=("Segoe UI", 10, "bold")).pack(side="left")
        self.client_var = tk.StringVar()
        self.client_combo = ttk.Combobox(top, textvariable=self.client_var, state="readonly", width=55)
        self.client_combo.pack(side="left", padx=8)
        self.client_combo.bind("<<ComboboxSelected>>", lambda e: self._on_client_selected())
        ttk.Button(top, text="Carica", command=self._on_client_selected).pack(side="left", padx=4)
        ttk.Button(top, text="Salva input", command=self.save_inputs).pack(side="left", padx=4)
        ttk.Button(top, text="Esegui analisi", command=self.run_analysis).pack(side="left", padx=4)
        ttk.Button(top, text="Apri cartella Scoring Plus", command=self.open_scoring_folder).pack(side="right")

        self.status_var = tk.StringVar(value="Seleziona un cliente per iniziare.")
        ttk.Label(root, textvariable=self.status_var, style="SubHeader.TLabel").pack(fill="x", pady=(0, 8))

        self.notebook = ttk.Notebook(root)
        self.notebook.pack(fill="both", expand=True)

        self._build_home_tab()
        self._build_input_tab()
        self._build_documents_tab()
        self._build_analysis_tab()

    def _build_home_tab(self):
        tab = ttk.Frame(self.notebook, padding=18)
        self.notebook.add(tab, text="Home Scoring Plus")
        box = ttk.LabelFrame(tab, text="Funzioni", padding=16)
        box.pack(fill="x", pady=(0, 16))
        ttk.Label(
            box,
            text=(
                "Questo modulo integra input dati, documenti e motore di scoring nel gestionale esistente. "
                "Compila i 5 fogli, salva i dati del cliente, allega i PDF e genera il report PDF di scoring."
            ),
            wraplength=980,
            justify="left",
        ).pack(anchor="w")
        grid = tk.Frame(tab, bg=BG_COLOR)
        grid.pack(fill="both", expand=True)
        TileButton(grid, "INPUT DATI", "Stato patrimoniale, CE, CR, estratti ed esposizioni", lambda: self.notebook.select(self.input_tab)).grid(row=0, column=0, padx=12, pady=12, sticky="nsew")
        TileButton(grid, "DOCUMENTI", "Allega bilanci, situazione, CR ed estratti", lambda: self.notebook.select(self.docs_tab)).grid(row=0, column=1, padx=12, pady=12, sticky="nsew")
        TileButton(grid, "SCORING/RATING", "Calcola rating, PD, importo e PDF", lambda: self.notebook.select(self.analysis_tab)).grid(row=0, column=2, padx=12, pady=12, sticky="nsew")
        for i in range(3):
            grid.columnconfigure(i, weight=1)

    def _build_input_tab(self):
        self.input_tab = ttk.Frame(self.notebook, padding=8)
