    def _build_sp_sheet(self, nb):
        tab = ttk.Frame(nb, padding=10)
        nb.add(tab, text="Stato patrimoniale")
        ttk.Label(tab, text="Attivo e passivo: 2 anni + situazione attuale", font=("Segoe UI", 11, "bold")).pack(anchor="w", pady=(0, 8))
        table = ttk.Frame(tab)
        table.pack(anchor="nw")
        ttk.Label(table, text="Voce", width=26).grid(row=0, column=0, padx=4, pady=4)
