def _cf_remove_responsible(self):
    try:
        self.collaborator_combo.set("")
    except Exception:
        pass
    if self.client_id is not None:
        if not messagebox.askyesno("Conferma", "Vuoi rimuovere subito il responsabile salvato per questo cliente?"):
            return
        self.db.clear_client_responsible(self.client_id)
        if self.on_saved:
            self.on_saved()
        messagebox.showinfo("Responsabile rimosso", "Responsabile cliente rimosso correttamente.")
    else:
        messagebox.showinfo("Responsabile rimosso", "Il campo responsabile è stato svuotato. Salva il cliente per confermare.")


