# ---------- Financial Pre-Evaluation ----------

def _prew_open_selected_document(self):
    ids = _fp_selected_int_ids_from_tree(self.docs_tree)
    if not ids:
        messagebox.showwarning("Attenzione", "Seleziona un documento da aprire.")
        return
    row = self.doc_rows_by_iid.get(str(ids[0])) or self.db.get_document(ids[0])
    if row and row["stored_path"]:
        open_path(row["stored_path"])
    else:
        messagebox.showerror("Errore", "Documento non trovato o file mancante.")


def _prew_delete_selected_documents(self):
    ids = _fp_selected_int_ids_from_tree(self.docs_tree)
    if not ids:
        messagebox.showwarning("Attenzione", "Seleziona almeno un documento da eliminare.")
        return
    if not messagebox.askyesno("Conferma eliminazione", f"Eliminare i documenti selezionati? ({len(ids)})"):
        return
    for document_id in ids:
        self.db.delete_document(document_id)
    self.current_result = None
    self.refresh_documents(auto_run=False)
    messagebox.showinfo("Eliminazione completata", "Documento/i eliminato/i.")


