def _sp_delete_inputs(self):
    if not getattr(self, "current_client_id", None):
        messagebox.showwarning("Scoring Plus", "Seleziona prima un cliente.")
        return
    if not messagebox.askyesno("Conferma eliminazione", "Vuoi eliminare tutti gli input dati salvati per il cliente selezionato?"):
        return
    self.db.delete_scoring_plus_input(self.current_client_id)
    for var in getattr(self, "inputs", {}).values():
        try:
            var.set("0")
        except Exception:
            pass
    try:
        self._refresh_kpi_preview()
    except Exception:
        pass
    self.status_var.set("Input dati eliminati per il cliente selezionato.")
    messagebox.showinfo("Eliminazione completata", "Input dati eliminati correttamente.")


def _sp_delete_selected_document(self):
    ids = _fp_selected_int_ids_from_tree(self.docs_tree)
    if not ids:
        messagebox.showwarning("Documenti", "Seleziona un documento da eliminare.")
        return
    if not messagebox.askyesno("Conferma eliminazione", f"Eliminare i documenti selezionati? ({len(ids)})"):
        return
    for document_id in ids:
        self.db.delete_scoring_plus_document(document_id)
    self.refresh_documents()
    self.status_var.set("Documento/i eliminato/i.")
    messagebox.showinfo("Eliminazione completata", "Documento/i eliminato/i correttamente.")


def _sp_delete_all_documents_for_client(self):
    if not getattr(self, "current_client_id", None):
        messagebox.showwarning("Documenti", "Seleziona prima un cliente.")
        return
    if not messagebox.askyesno("Conferma eliminazione", "Vuoi eliminare tutti i documenti Scoring Plus del cliente selezionato?"):
        return
    self.db.delete_scoring_plus_documents_for_client(self.current_client_id)
    self.refresh_documents()
    self.status_var.set("Tutti i documenti Scoring Plus del cliente sono stati eliminati.")
    messagebox.showinfo("Eliminazione completata", "Documenti Scoring Plus eliminati.")


ScoringPlusWindow.delete_inputs = _sp_delete_inputs
