# ============================================================
# PATCH MODULO ANALISI CR 36 MESI
# - selezione cliente
# - caricamento CR singola o multipla
# - lettura testo da PDF/TXT/CSV/XLSX quando disponibile
# - report PDF dettagliato con indici, rate, interrogazioni,
#   segnalazioni, sconfinamenti e dettaglio mese per mese
# ============================================================

TILE_ICONS["ANALISI CR 36 MESI"] = "CR"

_CR36_MONTHS_IT = {
    "gennaio": 1, "febbraio": 2, "marzo": 3, "aprile": 4,
    "maggio": 5, "giugno": 6, "luglio": 7, "agosto": 8,
    "settembre": 9, "ottobre": 10, "novembre": 11, "dicembre": 12,
    "genn": 1, "feb": 2, "mar": 3, "apr": 4, "mag": 5,
    "giu": 6, "lug": 7, "ago": 8, "set": 9, "ott": 10,
    "nov": 11, "dic": 12,
}
_CR36_NUM_RE = r"[-+]?\d{1,3}(?:[\.\s]\d{3})*(?:,\d+)?|[-+]?\d+(?:[\.,]\d+)?"


def _cr36_read_text(path: str, max_chars: int = 160000) -> str:
    p = Path(path or "")
    if not p.exists():
        return ""
    for reader_name in ("_sp_read_any_document_text", "safe_read_document_text", "text_from_supported_file"):
        reader = globals().get(reader_name)
        if callable(reader):
            try:
                txt = reader(str(p))
                if txt and txt.strip():
                    return str(txt)[:max_chars]
            except Exception:
                pass
    try:
        return p.read_text(encoding="utf-8", errors="ignore")[:max_chars]
    except Exception:
        return ""


def _cr36_clean_text(text: str) -> str:
    text = (text or "").replace("\xa0", " ")
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


def _cr36_parse_num(value) -> float:
    if value is None:
        return 0.0
    s = str(value).strip().replace("EUR", "").replace("eur", "").replace("euro", "").replace(" ", "")
    s = re.sub(r"[^0-9,\.\-]", "", s)
    if not s or s in {"-", ".", ","}:
        return 0.0
    try:
        if "," in s and "." in s:
            if s.rfind(",") > s.rfind("."):
                s = s.replace(".", "").replace(",", ".")
            else:
                s = s.replace(",", "")
        elif "," in s:
            s = s.replace(".", "").replace(",", ".")
        elif "." in s:
            parts = s.split(".")
            if len(parts) > 1 and all(len(part) == 3 for part in parts[1:]) and len(parts[0]) <= 3:
                s = "".join(parts)
        return float(Decimal(s))
    except Exception:
        parsed = parse_number(str(value))
        return float(parsed or 0.0)


def _cr36_amount_after(block: str, keywords: list[str], default: float = 0.0) -> float:
    if not block:
        return default
    for keyword in keywords:
        # Search a short window after the label and take the largest plausible monetary value.
        pattern = re.compile(r"%s[^0-9\-]{0,100}(%s)" % (keyword, _CR36_NUM_RE), re.IGNORECASE)
        values = []
        for match in pattern.finditer(block):
            val = _cr36_parse_num(match.group(1))
            # Avoid dates/years when possible.
            if 1900 <= abs(val) <= 2099:
                continue
            values.append(val)
        if values:
            return max(values, key=lambda x: abs(x))
    return default


def _cr36_count_terms(block: str, terms: list[str]) -> int:
    low = normalize_category(block or "")
    total = 0
    for term in terms:
        total += len(re.findall(term, low, flags=re.IGNORECASE))
    return int(total)


def _cr36_count_or_number(block: str, label_keywords: list[str], term_patterns: list[str]) -> int:
    amount = _cr36_amount_after(block, label_keywords, default=0.0)
    if amount > 0 and amount < 1000:
        return int(round(amount))
    return _cr36_count_terms(block, term_patterns)


def _cr36_month_key(label: str) -> tuple[int, int]:
    m = re.search(r"(20\d{2})[-/\.](0?[1-9]|1[0-2])", label or "")
    if m:
        return int(m.group(1)), int(m.group(2))
    m = re.search(r"(0?[1-9]|1[0-2])[-/\.](20\d{2})", label or "")
    if m:
        return int(m.group(2)), int(m.group(1))
    return (9999, 99)


def _cr36_format_pct(value) -> str:
    if value is None:
        return "-"
    try:
        return f"{float(value):.1f}%"
    except Exception:
        return "-"


def _cr36_extract_row(label: str, block: str) -> dict:
    accordato = _cr36_amount_after(block, [
        r"accordato operativo", r"totale accordato", r"accordato", r"affidamento", r"fido"
    ])
    utilizzato = _cr36_amount_after(block, [
        r"utilizzato operativo", r"totale utilizzato", r"utilizzato", r"utilizzo", r"esposizione"
    ])
    sconfinamenti = _cr36_amount_after(block, [
        r"sconfinament[oi]", r"sconfino", r"extra fido", r"oltre il fido", r"utilizzato oltre"
    ])
    rate = _cr36_amount_after(block, [
        r"rata mensile", r"rate mensili", r"rata", r"rate", r"rimborso mensile", r"canone"
    ])
    scaduto = _cr36_amount_after(block, [
        r"scaduto", r"rate scadute", r"past due", r"insolut[oi]", r"ritard[oi]"
    ])
    sofferenze = _cr36_amount_after(block, [r"sofferenz[ae]", r"credito deteriorato", r"deteriorat[oi]"])
    garanzie = _cr36_amount_after(block, [r"garanzie ricevute", r"garanzie", r"garantito"])
    interrogazioni = _cr36_count_or_number(
        block,
        [r"interrogazion[ei]", r"richieste prima informazione", r"richieste di prima informazione", r"accessi"],
        [r"interrogazion", r"prima informazione", r"access[io]", r"consultazion"],
    )
    segnalazioni = _cr36_count_or_number(
        block,
        [r"segnalazion[ei]", r"numero segnalazioni"],
        [r"segnalazion", r"sofferenz", r"inadempienz", r"past due", r"scadut", r"sconfin", r"revoca", r"incagli"],
    )
    utilizzo_pct = None
    if accordato:
        utilizzo_pct = (utilizzato / accordato) * 100.0
    flags = []
    if utilizzo_pct is not None and utilizzo_pct >= 90:
        flags.append("utilizzo >=90%")
    elif utilizzo_pct is not None and utilizzo_pct >= 75:
        flags.append("utilizzo 75-90%")
    if sconfinamenti > 0:
        flags.append("sconfino")
    if scaduto > 0 or rate > 0:
        flags.append("rate/scaduti")
    if sofferenze > 0 or _cr36_count_terms(block, [r"sofferenz", r"inadempienz", r"deteriorat"]) > 0:
        flags.append("criticita")
    if interrogazioni > 0:
        flags.append("interrogazioni")
    return {
        "mese": label,
        "accordato": accordato,
        "utilizzato": utilizzato,
        "utilizzo_pct": utilizzo_pct,
        "sconfinamenti": sconfinamenti,
        "rate_mensili": rate,
        "scaduto": scaduto,
        "interrogazioni": interrogazioni,
        "segnalazioni": segnalazioni,
        "sofferenze": sofferenze,
        "garanzie": garanzie,
        "note": ", ".join(flags) if flags else "regolare/non rilevato",
    }


def _cr36_find_month_blocks(text: str) -> list[tuple[str, str]]:
    text = _cr36_clean_text(text)
    if not text:
        return []
    markers: list[tuple[int, str]] = []
    month_names = "|".join(sorted(_CR36_MONTHS_IT.keys(), key=len, reverse=True))
    for m in re.finditer(r"\b(" + month_names + r")\s+(20\d{2})\b", text, flags=re.IGNORECASE):
        month = _CR36_MONTHS_IT.get(normalize_category(m.group(1)), 0)
        if month:
            markers.append((m.start(), f"{m.group(2)}-{month:02d}"))
    for m in re.finditer(r"\b(0?[1-9]|1[0-2])[\-/\.](20\d{2})\b", text):
        markers.append((m.start(), f"{m.group(2)}-{int(m.group(1)):02d}"))
    for m in re.finditer(r"\b(20\d{2})[\-/\.](0?[1-9]|1[0-2])\b", text):
        markers.append((m.start(), f"{m.group(1)}-{int(m.group(2)):02d}"))
    if not markers:
        return [("Documento", text)]
    # Deduplicate near-identical labels found at the same position/window.
    markers = sorted(markers, key=lambda x: x[0])
    compact: list[tuple[int, str]] = []
    seen_positions = set()
    for pos, label in markers:
        key = (label, pos // 400)
        if key in seen_positions:
            continue
        seen_positions.add(key)
        compact.append((pos, label))
    blocks = []
    for idx, (pos, label) in enumerate(compact):
        next_pos = compact[idx + 1][0] if idx + 1 < len(compact) else len(text)
        block = text[pos:next_pos]
        if block.strip():
            blocks.append((label, block))
    return blocks


def _cr36_parse_monthly_rows(text: str) -> list[dict]:
    blocks = _cr36_find_month_blocks(text)
    rows_by_month: dict[str, dict] = {}
    for label, block in blocks:
        row = _cr36_extract_row(label, block)
        existing = rows_by_month.get(label)
        if existing:
            for key in ("accordato", "utilizzato", "sconfinamenti", "rate_mensili", "scaduto", "sofferenze", "garanzie"):
                existing[key] = max(float(existing.get(key) or 0), float(row.get(key) or 0))
            existing["interrogazioni"] = int(existing.get("interrogazioni") or 0) + int(row.get("interrogazioni") or 0)
            existing["segnalazioni"] = int(existing.get("segnalazioni") or 0) + int(row.get("segnalazioni") or 0)
            notes = {n.strip() for n in (existing.get("note", "") + ", " + row.get("note", "")).split(",") if n.strip()}
            existing["note"] = ", ".join(sorted(notes)) if notes else "regolare/non rilevato"
            if existing.get("accordato"):
                existing["utilizzo_pct"] = (existing.get("utilizzato") or 0) / existing.get("accordato") * 100.0
        else:
            rows_by_month[label] = row
    rows = list(rows_by_month.values())
    rows.sort(key=lambda r: _cr36_month_key(r.get("mese", "")))
    if len(rows) > 36:
        rows = rows[-36:]
    return rows


def _cr36_avg(values: list[float]) -> float:
    vals = [float(v) for v in values if v is not None]
    return sum(vals) / len(vals) if vals else 0.0


def _cr36_build_summary(rows: list[dict]) -> dict:
    ratios = [r.get("utilizzo_pct") for r in rows if r.get("utilizzo_pct") is not None]
    used = [r.get("utilizzato") or 0 for r in rows]
    accorded = [r.get("accordato") or 0 for r in rows]
    sconf = [r.get("sconfinamenti") or 0 for r in rows]
    rate = [r.get("rate_mensili") or 0 for r in rows]
    seg = [int(r.get("segnalazioni") or 0) for r in rows]
    interr = [int(r.get("interrogazioni") or 0) for r in rows]
    critical_months = sum(1 for r in rows if (r.get("sconfinamenti") or 0) > 0 or (r.get("sofferenze") or 0) > 0 or (r.get("scaduto") or 0) > 0 or int(r.get("segnalazioni") or 0) > 0)
    recent_trend = "N/D"
    if len(used) >= 6:
        first = _cr36_avg(used[:3])
        last = _cr36_avg(used[-3:])
        if first:
            delta = (last - first) / abs(first) * 100.0
            recent_trend = f"{delta:+.1f}% ultimo trimestre vs primo trimestre"
    avg_ratio = _cr36_avg(ratios)
    max_ratio = max(ratios) if ratios else 0.0
    risk_points = 0
    if avg_ratio >= 85: risk_points += 2
    elif avg_ratio >= 70: risk_points += 1
    if max_ratio >= 100: risk_points += 2
    elif max_ratio >= 90: risk_points += 1
    if critical_months >= 6: risk_points += 2
    elif critical_months >= 1: risk_points += 1
    if sum(sconf) > 0: risk_points += 1
    if sum(seg) > 0: risk_points += 1
    if risk_points >= 5:
        giudizio = "Critico"
    elif risk_points >= 3:
        giudizio = "Da presidiare"
    else:
        giudizio = "Regolare/monitorare"
    return {
        "mesi_analizzati": len(rows),
        "accordato_medio": _cr36_avg(accorded),
        "accordato_max": max(accorded) if accorded else 0.0,
        "utilizzato_medio": _cr36_avg(used),
        "utilizzato_max": max(used) if used else 0.0,
        "utilizzo_medio_pct": avg_ratio,
        "utilizzo_max_pct": max_ratio,
        "sconfinamenti_totali": sum(sconf),
        "mesi_con_sconfini": sum(1 for v in sconf if v > 0),
        "rate_medie": _cr36_avg(rate),
        "rate_max": max(rate) if rate else 0.0,
        "interrogazioni_totali": sum(interr),
        "segnalazioni_totali": sum(seg),
        "mesi_critici": critical_months,
        "trend_utilizzato": recent_trend,
        "giudizio": giudizio,
        "risk_points": risk_points,
    }


def _cr36_build_report(client_row, docs: list, rows: list[dict]) -> dict:
    summary = _cr36_build_summary(rows)
    client_name = client_row["denominazione"] if client_row else "Cliente"
    doc_names = ", ".join([d["original_filename"] or d["title"] or "Documento CR" for d in docs]) if docs else "Nessun documento"
    sections = [
        [
            "1. Sintesi Analisi CR 36 mesi",
            f"Cliente: {client_name}. Documenti analizzati: {doc_names}.",
            f"Mesi riconosciuti: {summary['mesi_analizzati']}. Giudizio automatico: {summary['giudizio']}.",
            f"Utilizzo medio accordato: {_cr36_format_pct(summary['utilizzo_medio_pct'])}; picco utilizzo: {_cr36_format_pct(summary['utilizzo_max_pct'])}. Trend utilizzato: {summary['trend_utilizzato']}.",
        ],
        [
            "2. Indici principali",
            f"Accordato medio: {format_currency(summary['accordato_medio'])}; accordato massimo: {format_currency(summary['accordato_max'])}.",
            f"Utilizzato medio: {format_currency(summary['utilizzato_medio'])}; utilizzato massimo: {format_currency(summary['utilizzato_max'])}.",
            f"Sconfinamenti totali rilevati: {format_currency(summary['sconfinamenti_totali'])}; mesi con sconfini: {summary['mesi_con_sconfini']}.",
            f"Rate mensili medie rilevate/stimate da documento: {format_currency(summary['rate_medie'])}; rata massima: {format_currency(summary['rate_max'])}.",
        ],
        [
            "3. Interrogazioni, segnalazioni e anomalie",
            f"Interrogazioni/consultazioni rilevate: {summary['interrogazioni_totali']}. Segnalazioni/parole critiche rilevate: {summary['segnalazioni_totali']}.",
            f"Mesi critici: {summary['mesi_critici']} su {summary['mesi_analizzati']}.",
            "Il report PDF include la tabella mese per mese con accordato, utilizzato, sconfinamenti, rate/scaduti, interrogazioni, segnalazioni, sofferenze e garanzie.",
        ],
        [
            "4. Raccomandazioni operative",
            "Presidiare i mesi con utilizzo superiore al 90%, sconfinamenti, rate scadute o segnalazioni critiche prima di inviare la pratica in istruttoria.",
            "Se emergono picchi di breve termine, valutare consolidamento del debito, rinegoziazione affidamenti o presentazione di commento andamentale alla banca.",
        ],
    ]
    return {"title": "Analisi CR 36 mesi", "sections": sections, "summary": summary, "rows": rows, "docs": docs}


def _cr36_para(text, style):
    return Paragraph(html.escape(str(text or "")).replace("\n", "<br/>"), style)


def _cr36_export_pdf(output_path: str, client_row, report: dict) -> None:
    if not REPORTLAB_AVAILABLE:
        raise RuntimeError("ReportLab non disponibile: impossibile generare il PDF.")
    from reportlab.lib.pagesizes import landscape
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle("CR36Title", parent=styles["Heading1"], fontName="Helvetica-Bold", fontSize=18, leading=22, textColor=colors.HexColor("#1f4ea8"), spaceAfter=10)
    h2 = ParagraphStyle("CR36H2", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=12, leading=15, textColor=colors.HexColor("#1f4ea8"), spaceBefore=8, spaceAfter=5)
    body = ParagraphStyle("CR36Body", parent=styles["BodyText"], fontName="Helvetica", fontSize=8.3, leading=10.5, spaceAfter=4)
    small = ParagraphStyle("CR36Small", parent=styles["BodyText"], fontName="Helvetica", fontSize=6.5, leading=8)
    doc = SimpleDocTemplate(output_path, pagesize=landscape(A4), leftMargin=1.2*cm, rightMargin=1.2*cm, topMargin=2.4*cm, bottomMargin=1.2*cm)
    story = [_cr36_para(report.get("title") or "Analisi CR 36 mesi", title_style)]
    if client_row:
        story.append(_cr36_para(f"Cliente: {client_row['denominazione']}", body))
    story.append(_cr36_para(f"Data report: {datetime.now().strftime('%d/%m/%Y %H:%M')}", body))
    story.append(Spacer(1, 0.2*cm))

    for section in report.get("sections", []):
        if not section:
            continue
        story.append(_cr36_para(section[0], h2))
        for par in section[1:]:
            story.append(_cr36_para(par, body))
        story.append(Spacer(1, 0.1*cm))

    summary = report.get("summary", {})
    idx_rows = [["Indice", "Valore"],
        ["Mesi analizzati", summary.get("mesi_analizzati", 0)],
        ["Accordato medio", format_currency(summary.get("accordato_medio"))],
        ["Utilizzato medio", format_currency(summary.get("utilizzato_medio"))],
        ["Utilizzo medio", _cr36_format_pct(summary.get("utilizzo_medio_pct"))],
        ["Picco utilizzo", _cr36_format_pct(summary.get("utilizzo_max_pct"))],
        ["Mesi con sconfini", summary.get("mesi_con_sconfini", 0)],
        ["Sconfinamenti totali", format_currency(summary.get("sconfinamenti_totali"))],
        ["Rate medie rilevate", format_currency(summary.get("rate_medie"))],
        ["Interrogazioni", summary.get("interrogazioni_totali", 0)],
        ["Segnalazioni", summary.get("segnalazioni_totali", 0)],
        ["Mesi critici", summary.get("mesi_critici", 0)],
        ["Giudizio", summary.get("giudizio", "-")],
    ]
    idx_table = Table(idx_rows, colWidths=[5.2*cm, 6.2*cm])
    idx_table.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), colors.HexColor(ACCENT_COLOR)),
        ("GRID", (0,0), (-1,-1), 0.25, colors.grey),
        ("FONTNAME", (0,0), (-1,0), "Helvetica-Bold"),
        ("FONTSIZE", (0,0), (-1,-1), 8),
        ("VALIGN", (0,0), (-1,-1), "TOP"),
    ]))
    story += [_cr36_para("5. Tabella indici", h2), idx_table, Spacer(1, 0.25*cm)]

    rows = report.get("rows", [])
    table_rows = [["Mese", "Accordato", "Utilizzato", "Util.%", "Sconfini", "Rate/Scaduti", "Int.", "Segn.", "Soff.", "Garanzie", "Note"]]
    for r in rows:
        rate_scad = max(float(r.get("rate_mensili") or 0), float(r.get("scaduto") or 0))
        table_rows.append([
            r.get("mese", ""),
            format_currency(r.get("accordato")),
            format_currency(r.get("utilizzato")),
            _cr36_format_pct(r.get("utilizzo_pct")),
            format_currency(r.get("sconfinamenti")),
            format_currency(rate_scad),
            str(r.get("interrogazioni") or 0),
            str(r.get("segnalazioni") or 0),
            format_currency(r.get("sofferenze")),
            format_currency(r.get("garanzie")),
            _cr36_para(r.get("note", ""), small),
        ])
    monthly_table = Table(table_rows, repeatRows=1, colWidths=[1.55*cm, 2.25*cm, 2.25*cm, 1.35*cm, 2.0*cm, 2.05*cm, 0.9*cm, 1.0*cm, 1.85*cm, 1.95*cm, 4.6*cm])
    monthly_table.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), colors.HexColor("#dfe9ff")),
        ("GRID", (0,0), (-1,-1), 0.20, colors.grey),
        ("FONTNAME", (0,0), (-1,0), "Helvetica-Bold"),
        ("FONTSIZE", (0,0), (-1,-1), 6.4),
        ("VALIGN", (0,0), (-1,-1), "TOP"),
        ("ALIGN", (1,1), (9,-1), "RIGHT"),
    ]))
    story += [_cr36_para("6. Dettaglio mese per mese - CR 36 mesi", h2), monthly_table, Spacer(1, 0.25*cm)]

    alerts = [["Mese", "Interrogazioni", "Segnalazioni", "Sconfinamenti", "Rate/Scaduti", "Nota"]]
    for r in rows:
        if int(r.get("interrogazioni") or 0) or int(r.get("segnalazioni") or 0) or (r.get("sconfinamenti") or 0) or (r.get("scaduto") or 0) or (r.get("rate_mensili") or 0):
            alerts.append([
                r.get("mese", ""), str(r.get("interrogazioni") or 0), str(r.get("segnalazioni") or 0),
                format_currency(r.get("sconfinamenti")), format_currency(max(float(r.get("rate_mensili") or 0), float(r.get("scaduto") or 0))),
                _cr36_para(r.get("note", ""), small),
            ])
    if len(alerts) == 1:
        alerts.append(["-", "0", "0", "-", "-", "Nessuna anomalia rilevata dal testo estraibile."])
    alert_table = Table(alerts, repeatRows=1, colWidths=[2.0*cm, 2.2*cm, 2.2*cm, 3.0*cm, 3.0*cm, 10.0*cm])
    alert_table.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), colors.HexColor("#fff2cc")),
        ("GRID", (0,0), (-1,-1), 0.20, colors.grey),
        ("FONTNAME", (0,0), (-1,0), "Helvetica-Bold"),
        ("FONTSIZE", (0,0), (-1,-1), 6.8),
        ("VALIGN", (0,0), (-1,-1), "TOP"),
    ]))
    story += [_cr36_para("7. Tabella interrogazioni, segnalazioni, sconfinamenti e rate", h2), alert_table]
    story += [Spacer(1, 0.2*cm), _cr36_para("Nota: analisi automatica basata sul testo estraibile dal documento. In caso di PDF scansionato o tabelle non testuali, verificare i dati e integrare manualmente.", small)]

    def add_page(canv, _doc):
        draw_pdf_branding(canv, report.get("title") or "Analisi CR 36 mesi")
        canv.saveState()
        canv.setFont("Helvetica", 8)
        canv.setFillColor(colors.HexColor("#6b778c"))
        canv.drawRightString(landscape(A4)[0] - 1.2*cm, 0.8*cm, f"Pagina {canv.getPageNumber()}")
        canv.restoreState()
    doc.build(story, onFirstPage=add_page, onLaterPages=add_page)


class CR36AnalysisWindow(ReportBaseWindow):
    def __init__(self, master, db: Database, preselected_client_id: int | None = None):
        super().__init__(master, db, "Analisi CR 36 mesi", ["Centrale Rischi"], preselected_client_id)
        self.current_cr36_report = None
        self.current_cr36_pdf_path = None
        try:
            body = self.content_frame.winfo_children()[3]
        except Exception:
            body = None
        controls = ttk.LabelFrame(self.content_frame, text="Modulo CR 36 mesi", padding=10)
        if body is not None:
            controls.pack(fill="x", padx=16, pady=(0, 10), before=body)
        else:
            controls.pack(fill="x", padx=16, pady=(0, 10))
        ttk.Button(controls, text="Carica CR PDF/multipli", command=self.upload_cr_documents).pack(side="left")
        ttk.Button(controls, text="Analizza e crea PDF", command=self.run_analysis).pack(side="left", padx=(8, 0))
        ttk.Button(controls, text="Esporta PDF dettagliato", command=self.export_pdf).pack(side="left", padx=(8, 0))
        ttk.Label(controls, text="Seleziona cliente, carica la Centrale Rischi e genera il report con dettaglio mese per mese.", foreground=MUTED_TEXT).pack(side="left", padx=12)

    def upload_cr_documents(self):
        client_id = self.selected_client_id()
        if not client_id:
            messagebox.showwarning("Attenzione", "Seleziona prima un cliente.")
            return
        paths = filedialog.askopenfilenames(
            title="Seleziona Centrale Rischi",
            filetypes=[("Documenti CR", "*.pdf *.xlsx *.xls *.csv *.txt *.docx"), ("PDF", "*.pdf"), ("Tutti i file", "*.*")],
        )
        if not paths:
            return
        client = self.db.get_client(client_id)
        collaborator_id = None
        try:
            collaborator_id = client["responsible_collaborator_id"]
        except Exception:
            collaborator_id = None
        added = 0
        for p in paths:
            try:
                stored_path = archive_document_file(client_id, p, prefix="centrale_rischi")
                title = f"CR 36 mesi - {Path(p).stem}"
                notes = "Documento caricato dal modulo Analisi CR 36 mesi. Categoria forzata: Centrale Rischi."
                doc_id = self.db.add_document({
                    "client_id": client_id,
                    "collaborator_id": collaborator_id,
                    "category": "Centrale Rischi",
                    "title": title,
                    "original_filename": Path(p).name,
                    "stored_path": stored_path,
                    "notes": notes,
                })
                if callable(globals().get("mirror_document_to_scoring_plus")):
                    try:
                        mirror_document_to_scoring_plus(self.db, client_id, "Centrale Rischi", Path(p).name, stored_path, notes)
                    except Exception:
                        pass
                added += 1
            except Exception as exc:
                messagebox.showerror("Errore caricamento", f"Impossibile caricare {p}\n\n{exc}")
        self.refresh_documents()
        messagebox.showinfo("Caricamento completato", f"Documenti CR caricati: {added}")

    def _cr_docs_to_analyze(self) -> list:
        row = self.selected_document()
        if row and (row["stored_path"] or ""):
            return [row]
        client_id = self.selected_client_id()
        if not client_id:
            return []
        rows = pick_documents_for_categories(self.db, client_id, ["Centrale Rischi"])
        return list(rows or [])

    def run_analysis(self):
        client_id = self.selected_client_id()
        if not client_id:
            messagebox.showwarning("Attenzione", "Seleziona un cliente.")
            return
        docs = self._cr_docs_to_analyze()
        if not docs:
            if messagebox.askyesno("Nessuna CR", "Non trovo una Centrale Rischi per il cliente. Vuoi caricarla ora?"):
                self.upload_cr_documents()
                docs = self._cr_docs_to_analyze()
            if not docs:
                return
        client = self.db.get_client(client_id)
        text_parts = []
        for row in docs:
            txt = _cr36_read_text(row["stored_path"] or "")
            if txt.strip():
                text_parts.append(f"\n--- {row['original_filename'] or row['title'] or 'Documento CR'} ---\n{txt}")
        full_text = _cr36_clean_text("\n".join(text_parts))
        if not full_text:
            messagebox.showwarning("Testo non leggibile", "Il documento non contiene testo estraibile. Se e' una scansione, serve un PDF OCR/testuale.")
            return
        rows = _cr36_parse_monthly_rows(full_text)
        report = _cr36_build_report(client, docs, rows)
        self.current_cr36_report = report
        self.current_pdf_title = report["title"]
        self.set_report(report["sections"], report["title"])
        self.draw_chart(rows, report.get("summary", {}))
        try:
            folder = get_client_documents_folder(client_id)
            safe_client = sanitize_client_storage_name(client["denominazione"] if client else "cliente", f"cliente_{client_id}")
            stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            pdf_path = folder / f"{stamp}_Analisi_CR_36_mesi_{safe_client}.pdf"
            _cr36_export_pdf(str(pdf_path), client, report)
            self.current_cr36_pdf_path = str(pdf_path)
            try:
                self.db.add_document({
                    "client_id": client_id,
                    "collaborator_id": None,
                    "category": "Report",
                    "title": f"Analisi CR 36 mesi - {client['denominazione'] if client else client_id}",
                    "original_filename": pdf_path.name,
                    "stored_path": str(pdf_path),
                    "notes": "Report PDF creato automaticamente dal modulo Analisi CR 36 mesi.",
                })
                self.refresh_documents()
            except Exception:
                pass
            msg = f"Report PDF CR 36 mesi creato:\n{pdf_path}\n\nVuoi aprirlo ora?"
            if messagebox.askyesno("Report creato", msg):
                open_path(str(pdf_path))
        except Exception as exc:
            messagebox.showerror("Errore PDF", f"Impossibile creare il report PDF.\n\n{exc}")

    def export_pdf(self):
        if not self.current_cr36_report:
            messagebox.showwarning("Attenzione", "Esegui prima l'analisi CR 36 mesi.")
            return
        client_id = self.selected_client_id()
        client = self.db.get_client(client_id) if client_id else None
        path = filedialog.asksaveasfilename(
            title="Salva report CR 36 mesi",
            defaultextension=".pdf",
            initialfile="Analisi_CR_36_mesi.pdf",
            filetypes=[("PDF", "*.pdf")],
        )
        if not path:
            return
        try:
            _cr36_export_pdf(path, client, self.current_cr36_report)
            open_path(path)
        except Exception as exc:
            messagebox.showerror("Errore PDF", f"Impossibile esportare il PDF.\n\n{exc}")

    def draw_chart(self, rows: list[dict], summary: dict):
        c = self.chart_canvas
        c.delete("all")
        c.create_text(16, 16, anchor="nw", text="CR 36 mesi - utilizzo accordato", font=("Segoe UI", 11, "bold"), fill=TEXT_COLOR)
        if not rows:
            c.create_text(16, 50, anchor="nw", text="Nessun mese rilevato")
            return
        ratios = [r.get("utilizzo_pct") or 0 for r in rows]
        max_ratio = max(ratios + [1])
        width = int(c.winfo_width() or 360) - 40
        height = int(c.winfo_height() or 260)
        base_y = height - 38
        bar_w = max(4, min(18, int(width / max(len(rows), 1)) - 2))
        x = 22
        for idx, r in enumerate(rows):
            ratio = r.get("utilizzo_pct") or 0
            h = min(150, (ratio / max(max_ratio, 100)) * 150)
            color = WARNING_COLOR if ratio >= 90 or (r.get("sconfinamenti") or 0) > 0 else PRIMARY_COLOR
            c.create_rectangle(x, base_y - h, x + bar_w, base_y, fill=color, outline=color)
            if idx % max(1, len(rows)//6) == 0:
                c.create_text(x, base_y + 12, text=str(r.get("mese", ""))[-5:], font=("Segoe UI", 7), anchor="n")
            x += bar_w + 2
        c.create_text(16, 48, anchor="nw", text=f"Mesi: {summary.get('mesi_analizzati', len(rows))} | Utilizzo medio: {_cr36_format_pct(summary.get('utilizzo_medio_pct'))}", font=("Segoe UI", 9))
        c.create_text(16, 68, anchor="nw", text=f"Sconfini: {summary.get('mesi_con_sconfini', 0)} mesi | Giudizio: {summary.get('giudizio', '-')}", font=("Segoe UI", 9, "bold"))


