    self.tree.bind("<<TreeviewSelect>>", lambda _e: self.update_document_preview(), add="+")
    self.tree.bind("<ButtonRelease-1>", lambda _e: self.update_document_preview(), add="+")
    self.tree.bind("<Double-1>", lambda _e: self.open_selected(), add="+")

