# === PATCH MODULO 2 DASHBOARD OPERATIVA E PROMEMORIA ===
# Dashboard iniziale operativa + scadenze/promemoria automatici.
# Non modifica i dati esistenti: calcola tutto da clienti, documenti e richieste gia presenti.

M2_REQUIRED_DOCS = [
    {
        "nome": "Documento identita",
        "keywords": ["identita", "identita", "carta identita", "documento identita", "documento"],
        "validita_giorni": 3650,
        "bloccante": True,
    },
    {
        "nome": "Codice fiscale",
        "keywords": ["codice fiscale", "cf", "tessera sanitaria"],
        "validita_giorni": None,
        "bloccante": True,
    },
    {
        "nome": "Visura camerale",
        "keywords": ["visura", "visura camerale"],
        "validita_giorni": 180,
        "bloccante": True,
    },
    {
        "nome": "Bilancio",
        "keywords": ["bilancio", "situazione aggiornata", "situazione contabile", "bozza bilancio"],
        "validita_giorni": 365,
        "bloccante": True,
    },
    {
        "nome": "Centrale Rischi",
        "keywords": ["centrale rischi", "cr", "c.r.", "rischi"],
        "validita_giorni": 30,
        "bloccante": True,
    },
    {
        "nome": "Privacy / mandato",
        "keywords": ["privacy", "mandato", "contratto", "incarico"],
        "validita_giorni": None,
        "bloccante": True,
    },
]


def _m2_norm(value):
    try:
        return normalize_category(value or "")
    except Exception:
        return str(value or "").lower().replace("_", " ").strip()


def _m2_get(row, key, default=""):
    try:
        return row[key]
    except Exception:
        try:
            return getattr(row, key, default)
        except Exception:
            return default


def _m2_parse_date(value):
    if not value:
        return None
    txt = str(value).strip()[:10]
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y"):
        try:
            return datetime.strptime(txt, fmt).date()
        except Exception:
            pass
    return None


def _m2_days_from(value):
    d = _m2_parse_date(value)
    if not d:
        return None
    try:
        return (datetime.now().date() - d).days
    except Exception:
        return None


def _m2_doc_text(row):
    pieces = [
        _m2_get(row, "category"),
        _m2_get(row, "title"),
        _m2_get(row, "original_filename"),
        _m2_get(row, "notes"),
    ]
    return _m2_norm(" ".join(str(x or "") for x in pieces))


def _m2_list_docs(db, client_id):
    try:
        return list(db.list_documents_linked(client_id) or [])
    except Exception:
        try:
            return list(db.list_documents(client_id) or [])
        except Exception:
            return []


def _m2_list_reqs(db, client_id):
    try:
        return list(db.list_requests(client_id) or [])
    except Exception:
        return []


def _m2_doc_match(row, keywords):
    blob = _m2_doc_text(row)
    for k in keywords:
        kk = _m2_norm(k)
        if kk and (kk in blob or (kk == "cr" and " cr " in f" {blob} ")):
            return True
    return False


def _m2_uploaded_date(row):
    return _m2_get(row, "uploaded_at") or _m2_get(row, "created_at") or ""


def _m2_checklist(db, client_id):
    docs = _m2_list_docs(db, client_id)
    out = []
    for req in M2_REQUIRED_DOCS:
        found = None
        for d in docs:
            if _m2_doc_match(d, req["keywords"]):
                found = d
                break
        if not found:
            out.append({
                "documento": req["nome"],
                "stato": "MANCANTE",
                "data": "",
                "giorni": "",
                "note": "Documento obbligatorio mancante",
                "bloccante": req["bloccante"],
                "document_row": None,
            })
            continue
        uploaded = _m2_uploaded_date(found)
        days = _m2_days_from(uploaded)
        max_days = req.get("validita_giorni")
        if max_days is not None and days is not None and days > int(max_days):
            stato = "SCADUTO" if req["nome"] in ("Visura camerale", "Documento identita") else "DA AGGIORNARE"
            note = f"Caricato da {days} giorni. Validita consigliata: {max_days} giorni."
        elif req["nome"] == "Centrale Rischi" and days is not None and days > 30:
            stato = "DA AGGIORNARE"
            note = f"Centrale Rischi da aggiornare ogni mese. Documento caricato da {days} giorni."
        else:
            stato = "PRESENTE"
            note = "OK"
        out.append({
            "documento": req["nome"],
            "stato": stato,
            "data": str(uploaded)[:10] if uploaded else "",
            "giorni": "" if days is None else str(days),
            "note": note,
            "bloccante": req["bloccante"],
            "document_row": found,
        })
    return out


def _m2_request_open(row):
    txt = _m2_norm(( _m2_get(row, "status_detail") or "") + " " + (_m2_get(row, "request_status") or ""))
    if "evas" in txt and "inevas" not in txt and "parz" not in txt:
        return False
    if "chius" in txt or "complet" in txt:
        return False
    return True


def _m2_client_operational_status(checklist, requests):
    bad = [r for r in checklist if r["stato"] in ("MANCANTE", "SCADUTO", "DA AGGIORNARE")]
    bloccanti = [r for r in bad if r.get("bloccante")]
    open_reqs = [r for r in requests if _m2_request_open(r)]
    if bloccanti:
        return "BLOCCATA", "Manca o e scaduto un documento bloccante"
    if bad:
        return "PARZIALE", "Documenti da completare o aggiornare"
    if open_reqs:
        return "IN LAVORAZIONE", "Richieste ancora aperte"
    return "DA INVIARE", "Fascicolo documentale completo"


def _m2_responsible_name(db, client):
    rid = _m2_get(client, "responsible_collaborator_id")
    if not rid:
        return "Non assegnato"
    try:
        c = db.get_collaborator(int(rid))
        if c:
            return (str(_m2_get(c, "nome")) + " " + str(_m2_get(c, "cognome"))).strip()
    except Exception:
        pass
    return f"ID {rid}"


def _m2_request_days(row):
    return _m2_days_from(_m2_get(row, "request_date") or _m2_get(row, "created_at"))


def _m2_compute_dashboard(db, collaborator_id=None):
    clients = list(db.list_clients("") or [])
    if collaborator_id not in (None, "", "Tutti"):
        try:
            cid = int(collaborator_id)
            clients = [c for c in clients if int(_m2_get(c, "responsible_collaborator_id") or 0) == cid]
        except Exception:
            pass

    stats = {
        "Clienti totali": len(clients),
        "Pratiche bloccate": 0,
        "Pratiche parziali": 0,
        "Pratiche da inviare": 0,
        "Documenti mancanti": 0,
        "Documenti scaduti": 0,
        "Richieste inevase": 0,
        "Solleciti": 0,
    }
    blocked = []
    missing_docs = []
    open_reqs = []
    alerts = []

    for client in clients:
        client_id = int(_m2_get(client, "id"))
        cname = _m2_get(client, "denominazione") or f"Cliente {client_id}"
        resp = _m2_responsible_name(db, client)
        checklist = _m2_checklist(db, client_id)
        requests = _m2_list_reqs(db, client_id)
        status, reason = _m2_client_operational_status(checklist, requests)
        if status == "BLOCCATA":
            stats["Pratiche bloccate"] += 1
            blocked.append((client_id, cname, resp, status, reason))
        elif status == "PARZIALE":
            stats["Pratiche parziali"] += 1
        elif status == "DA INVIARE":
            stats["Pratiche da inviare"] += 1

        for item in checklist:
            if item["stato"] == "MANCANTE":
                stats["Documenti mancanti"] += 1
                missing_docs.append((client_id, cname, resp, item["documento"], item["stato"], item["data"], item["note"]))
                alerts.append(("ALTA", client_id, cname, resp, f"Manca documento: {item['documento']}", "Aperto"))
            elif item["stato"] in ("SCADUTO", "DA AGGIORNARE"):
                stats["Documenti scaduti"] += 1
                missing_docs.append((client_id, cname, resp, item["documento"], item["stato"], item["data"], item["note"]))
                prio = "ALTA" if item.get("bloccante") else "MEDIA"
                alerts.append((prio, client_id, cname, resp, f"Documento {item['documento']}: {item['stato']}", "Aperto"))

        for req in requests:
            if not _m2_request_open(req):
                continue
            days = _m2_request_days(req)
            subject = _m2_get(req, "request_subject") or _m2_get(req, "notes") or "Richiesta senza oggetto"
            rdate = _m2_get(req, "request_date") or _m2_get(req, "created_at") or ""
            open_reqs.append((client_id, cname, resp, str(subject)[:140], str(rdate)[:10], "" if days is None else str(days)))
            stats["Richieste inevase"] += 1
            if days is not None and days >= 7:
                stats["Solleciti"] += 1
                alerts.append(("MEDIA", client_id, cname, resp, f"Richiesta inevasa da {days} giorni: {str(subject)[:90]}", "Aperto"))

    return stats, blocked, missing_docs, open_reqs, alerts


def _m2_short(value, limit=120):
    txt = str(value or "").replace("\n", " ").strip()
    if len(txt) > limit:
        return txt[:limit - 3] + "..."
    return txt


def _m2_pdf_paragraph(value, style):
    try:
        return Paragraph(html.escape(str(value or "")), style)
    except Exception:
        return Paragraph(str(value or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"), style)


def _m2_collaborator_report_data(db, collaborator_id):
    clients_all = list(db.list_clients("") or [])
    clients = []
    try:
        cid_int = int(collaborator_id)
    except Exception:
        cid_int = 0
    for c in clients_all:
        try:
            if int(_m2_get(c, "responsible_collaborator_id") or 0) == cid_int:
                clients.append(c)
        except Exception:
            pass

    client_rows = []
    doc_rows = []
    req_rows = []

    for client in clients:
        client_id = int(_m2_get(client, "id"))
        cname = _m2_get(client, "denominazione") or f"Cliente {client_id}"
        checklist = _m2_checklist(db, client_id)
        requests = _m2_list_reqs(db, client_id)
        docs = _m2_list_docs(db, client_id)
        stato, motivo = _m2_client_operational_status(checklist, requests)
        missing = [x["documento"] for x in checklist if x["stato"] in ("MANCANTE", "SCADUTO", "DA AGGIORNARE")]
        open_requests = [r for r in requests if _m2_request_open(r)]
        client_rows.append({
            "client_id": client_id,
            "cliente": cname,
            "stato": stato,
            "motivo": motivo,
            "documenti_ricevuti": len(docs),
            "richieste_inevase": len(open_requests),
            "criticita": ", ".join(missing) if missing else "Nessuna",
        })

        for d in docs:
            doc_rows.append({
                "cliente": cname,
                "categoria": _m2_get(d, "category") or "Altro",
                "titolo": _m2_get(d, "title") or _m2_get(d, "original_filename") or "Documento",
                "file": _m2_get(d, "original_filename") or "",
                "data": str(_m2_get(d, "uploaded_at") or _m2_get(d, "created_at") or "")[:10],
                "caricato_da": _m2_get(d, "collaborator_name") or "",
                "note": _m2_get(d, "notes") or "",
            })

        for r in open_requests:
            days = _m2_request_days(r)
            req_rows.append({
                "cliente": cname,
                "data": str(_m2_get(r, "request_date") or _m2_get(r, "created_at") or "")[:10],
                "giorni": "" if days is None else str(days),
                "oggetto": _m2_get(r, "request_subject") or _m2_get(r, "notes") or "Richiesta senza oggetto",
                "stato": _m2_get(r, "status_detail") or _m2_get(r, "request_status") or "Inevasa",
                "canale": _m2_get(r, "contact_method") or "",
                "note": _m2_get(r, "notes") or "",
            })

    totals = {
        "Clienti assegnati": len(client_rows),
        "Documenti ricevuti": len(doc_rows),
        "Richieste inevase": len(req_rows),
        "Pratiche bloccate": len([r for r in client_rows if r["stato"] == "BLOCCATA"]),
        "Pratiche parziali": len([r for r in client_rows if r["stato"] == "PARZIALE"]),
        "Pratiche da inviare": len([r for r in client_rows if r["stato"] == "DA INVIARE"]),
    }
    return client_rows, doc_rows, req_rows, totals


class Module2DashboardWindow(BaseWindow):
    def __init__(self, master, db: Database):
        super().__init__(master, "Dashboard operativa - Modulo 2", "1460x880")
        self.db = db
        self.collaborator_map = {"Tutti": None}
        self.kpi_labels = {}
        self._build()
        self.refresh_dashboard()

    def _build(self):
        root = ttk.Frame(self.content_frame, padding=14)
        root.pack(fill="both", expand=True, padx=10, pady=10)
        root.columnconfigure(0, weight=1)
        root.rowconfigure(2, weight=1)

        top = ttk.Frame(root)
        top.grid(row=0, column=0, sticky="ew", pady=(0, 10))
        ttk.Label(top, text="Dashboard iniziale operativa", font=("Segoe UI", 16, "bold")).pack(side="left")
        ttk.Label(top, text="  Filtro collaboratore:").pack(side="left", padx=(24, 6))
        self.collab_var = tk.StringVar(value="Tutti")
        self.collab_combo = ttk.Combobox(top, textvariable=self.collab_var, state="readonly", width=32)
        self.collab_combo.pack(side="left")
        self.collab_combo.bind("<<ComboboxSelected>>", lambda _e: self.refresh_dashboard())
        ttk.Button(top, text="Aggiorna", command=self.refresh_dashboard).pack(side="left", padx=8)
        ttk.Button(top, text="Stampa / Esporta situazione", command=self.export_dashboard).pack(side="right")
        ttk.Button(top, text="Stampa collaboratore", command=self.export_collaborator_report).pack(side="right", padx=(0, 8))

        self.kpi_frame = ttk.Frame(root)
        self.kpi_frame.grid(row=1, column=0, sticky="ew", pady=(0, 10))
        for col in range(4):
            self.kpi_frame.columnconfigure(col, weight=1)

        self.nb = ttk.Notebook(root)
        self.nb.grid(row=2, column=0, sticky="nsew")

        self.tab_blocked = ttk.Frame(self.nb, padding=8)
        self.tab_docs = ttk.Frame(self.nb, padding=8)
        self.tab_reqs = ttk.Frame(self.nb, padding=8)
        self.tab_alerts = ttk.Frame(self.nb, padding=8)
        self.tab_help = ttk.Frame(self.nb, padding=12)
        self.nb.add(self.tab_blocked, text="Pratiche bloccate")
        self.nb.add(self.tab_docs, text="Documenti mancanti/scaduti")
        self.nb.add(self.tab_reqs, text="Richieste inevase")
        self.nb.add(self.tab_alerts, text="Promemoria automatici")
        self.nb.add(self.tab_help, text="Guida semplice")

        self.blocked_tree = self._make_tree(self.tab_blocked, ("cliente", "collaboratore", "stato", "motivo"), (260, 190, 130, 620))
        self.docs_tree = self._make_tree(self.tab_docs, ("cliente", "collaboratore", "documento", "stato", "data", "note"), (230, 170, 170, 120, 100, 560))
        self.reqs_tree = self._make_tree(self.tab_reqs, ("cliente", "collaboratore", "richiesta", "data", "giorni"), (240, 180, 640, 110, 110))
        self.alerts_tree = self._make_tree(self.tab_alerts, ("priorita", "cliente", "collaboratore", "avviso", "stato"), (100, 230, 170, 700, 110))

        for tree in (self.blocked_tree, self.docs_tree, self.reqs_tree, self.alerts_tree):
            tree.bind("<Double-1>", lambda e, t=tree: self.open_client_from_tree(t))

        btns = ttk.Frame(root)
        btns.grid(row=3, column=0, sticky="ew", pady=(8, 0))
        ttk.Button(btns, text="Apri cliente selezionato", command=self.open_selected_client_any).pack(side="left")
        ttk.Button(btns, text="Nuova richiesta", command=self.new_request_for_selected).pack(side="left", padx=6)
        ttk.Button(btns, text="Gestione documenti", command=self.open_document_management).pack(side="left", padx=6)
        ttk.Button(btns, text="Stampa situazione", command=self.export_dashboard).pack(side="right")
        ttk.Button(btns, text="Stampa collaboratore", command=self.export_collaborator_report).pack(side="right", padx=(0, 8))

        help_text = (
            "Come usare questa dashboard:\n\n"
            "1. Guarda i riquadri in alto: ti dicono subito quanti problemi ci sono.\n"
            "2. Apri la scheda 'Pratiche bloccate' per vedere i clienti fermi.\n"
            "3. Apri 'Documenti mancanti/scaduti' per sapere cosa devi chiedere al cliente.\n"
            "4. Apri 'Richieste inevase' per vedere cosa devi sollecitare.\n"
            "5. Usa il filtro collaboratore per controllare il lavoro di una sola persona.\n"
            "6. Doppio click su una riga per aprire il cliente.\n\n"
            "Regole automatiche:\n"
            "- Centrale Rischi: da aggiornare ogni 30 giorni.\n"
            "- Visura camerale: da aggiornare ogni 180 giorni.\n"
            "- Bilancio: da aggiornare ogni 365 giorni.\n"
            "- Richiesta aperta da almeno 7 giorni: da sollecitare.\n"
        )
        self.help_box = ScrolledText(self.tab_help, wrap="word", font=("Segoe UI", 11))
        self.help_box.pack(fill="both", expand=True)
        _c360_set_text(self.help_box, help_text) if '_c360_set_text' in globals() else self._set_text_plain(self.help_box, help_text)

    def _set_text_plain(self, widget, text):
        widget.configure(state="normal")
        widget.delete("1.0", "end")
        widget.insert("1.0", text)
        widget.configure(state="disabled")

    def _make_tree(self, parent, cols, widths):
        parent.rowconfigure(0, weight=1)
        parent.columnconfigure(0, weight=1)
        tree = ttk.Treeview(parent, columns=cols, show="headings", selectmode="browse")
        for col, width in zip(cols, widths):
            tree.heading(col, text=col.replace("_", " ").title())
            tree.column(col, width=width, anchor="w")
        tree.grid(row=0, column=0, sticky="nsew")
        y = ttk.Scrollbar(parent, orient="vertical", command=tree.yview)
        y.grid(row=0, column=1, sticky="ns")
        tree.configure(yscrollcommand=y.set)
        return tree

    def _refresh_collaborators(self):
        current = self.collab_var.get() if hasattr(self, "collab_var") else "Tutti"
        self.collaborator_map = {"Tutti": None}
        try:
            for row in self.db.list_collaborators(""):
                name = (str(_m2_get(row, "nome")) + " " + str(_m2_get(row, "cognome"))).strip()
                self.collaborator_map[name] = _m2_get(row, "id")
        except Exception:
            pass
        values = list(self.collaborator_map.keys())
        self.collab_combo["values"] = values
        if current in values:
            self.collab_var.set(current)
        else:
            self.collab_var.set("Tutti")

    def _selected_collaborator_id(self):
        return self.collaborator_map.get(self.collab_var.get())

    def _clear_tree(self, tree):
        for item in tree.get_children():
            tree.delete(item)

    def _insert(self, tree, iid, values):
        tree.insert("", "end", iid=str(iid), values=values)

    def _rebuild_kpis(self, stats):
        for w in self.kpi_frame.winfo_children():
            w.destroy()
        self.kpi_labels = {}
        items = list(stats.items())
        for idx, (title, value) in enumerate(items):
            card = tk.Frame(self.kpi_frame, bg=CARD_BG, highlightbackground=C360_BORDER if 'C360_BORDER' in globals() else '#D9E2F3', highlightthickness=1)
            card.grid(row=idx // 4, column=idx % 4, sticky="ew", padx=5, pady=5)
            tk.Label(card, text=title, bg=CARD_BG, fg=MUTED_TEXT, font=("Segoe UI", 9, "bold")).pack(anchor="w", padx=12, pady=(10, 0))
            color = PRIMARY_DARK
            if "bloccate" in title.lower() or "mancanti" in title.lower() or "scaduti" in title.lower():
                color = "#C23B22"
            elif "solleciti" in title.lower() or "inevase" in title.lower():
                color = "#F97316"
            tk.Label(card, text=str(value), bg=CARD_BG, fg=color, font=("Segoe UI", 20, "bold")).pack(anchor="w", padx=12, pady=(2, 10))

    def refresh_dashboard(self):
        self._refresh_collaborators()
        stats, blocked, docs, reqs, alerts = _m2_compute_dashboard(self.db, self._selected_collaborator_id())
        self._last_dashboard_data = (stats, blocked, docs, reqs, alerts)
        self._rebuild_kpis(stats)

        self._clear_tree(self.blocked_tree)
        for row in blocked:
            client_id, cliente, resp, stato, motivo = row
            self._insert(self.blocked_tree, client_id, (cliente, resp, stato, motivo))

        self._clear_tree(self.docs_tree)
        for idx, row in enumerate(docs):
            client_id, cliente, resp, doc, stato, data, note = row
            self._insert(self.docs_tree, f"{client_id}:doc:{idx}", (cliente, resp, doc, stato, data, note))

        self._clear_tree(self.reqs_tree)
        for idx, row in enumerate(reqs):
            client_id, cliente, resp, subject, rdate, days = row
            self._insert(self.reqs_tree, f"{client_id}:req:{idx}", (cliente, resp, subject, rdate, days))

        self._clear_tree(self.alerts_tree)
        for idx, row in enumerate(alerts):
            prio, client_id, cliente, resp, msg, stato = row
            self._insert(self.alerts_tree, f"{client_id}:alert:{idx}", (prio, cliente, resp, msg, stato))

    def _client_id_from_tree(self, tree):
        sel = tree.selection()
        if not sel:
            return None
        raw = str(sel[0])
        try:
            return int(raw.split(":")[0])
        except Exception:
            return None

    def open_client_from_tree(self, tree):
        cid = self._client_id_from_tree(tree)
        if cid is None:
            messagebox.showwarning("Cliente", "Seleziona una riga con un cliente.")
            return
        try:
            Client360Window(self, self.db, cid, on_changed=self.refresh_dashboard)
        except Exception:
            try:
                ClientDetailWindow(self, self.db, cid, on_changed=self.refresh_dashboard)
            except Exception as exc:
                messagebox.showerror("Cliente", str(exc))

    def open_selected_client_any(self):
        current = self.nb.nametowidget(self.nb.select())
        mapping = {
            self.tab_blocked: self.blocked_tree,
            self.tab_docs: self.docs_tree,
            self.tab_reqs: self.reqs_tree,
            self.tab_alerts: self.alerts_tree,
        }
        tree = mapping.get(current)
        if tree:
            self.open_client_from_tree(tree)

    def new_request_for_selected(self):
        current = self.nb.nametowidget(self.nb.select())
        mapping = {
            self.tab_blocked: self.blocked_tree,
            self.tab_docs: self.docs_tree,
            self.tab_reqs: self.reqs_tree,
            self.tab_alerts: self.alerts_tree,
        }
        tree = mapping.get(current)
        cid = self._client_id_from_tree(tree) if tree else None
        if cid is None:
            messagebox.showwarning("Richiesta", "Seleziona prima un cliente dalla dashboard.")
            return
        try:
            RequestFormDialog(self, self.db, cid, on_saved=self.refresh_dashboard)
        except TypeError:
            try:
                RequestFormDialog(self, self.db, cid, None, self.refresh_dashboard)
            except Exception as exc:
                messagebox.showerror("Richiesta", str(exc))

    def open_document_management(self):
        try:
            DocumentManagementWindow(self, self.db, on_saved=self.refresh_dashboard)
        except TypeError:
            DocumentManagementWindow(self, self.db)

