# === PATCH FULL TOP INTEGRATO ===
# Integrazione non distruttiva dei database caricati + dashboard piu robusta.
# File sorgente principale: MODULO2_STAMPA_COLLABORATORE.
# Funzioni aggiunte:
# - backup automatico prima di importare dati
# - ricerca database accanto al file .py: gestione_clienti.db, financeplustech.db, financeplus.db
# - unione non distruttiva di clienti, collaboratori, documenti e richieste
# - dashboard e scheda 360 estese anche ai documenti scoring_plus_documents
# - stampa collaboratore piu completa: clienti assegnati + pratiche collegate da documenti/richieste

try:
    APP_VERSION = str(APP_VERSION) + " FULL TOP"
except Exception:
    APP_VERSION = "FULL TOP"

FULL_TOP_DB_CANDIDATES = ("gestione_clienti.db", "financeplustech.db", "financeplus.db")
_FULL_TOP_IMPORT_STATUS = []


def _ft_now():
    try:
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return ""


def _ft_table_exists(conn, table_name):
    try:
        row = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table_name,)).fetchone()
        return bool(row)
    except Exception:
        return False


def _ft_columns(conn, table_name):
    try:
        return [r[1] for r in conn.execute(f"PRAGMA table_info({table_name})").fetchall()]
    except Exception:
        return []


def _ft_count(conn, table_name):
    try:
        if not _ft_table_exists(conn, table_name):
            return 0
        return int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0] or 0)
    except Exception:
        return 0


def _ft_norm_key(value):
    txt = str(value or "").strip().lower()
    txt = re.sub(r"[^a-z0-9]+", "", txt)
    return txt


def _ft_first(row, *keys):
    for key in keys:
        try:
            val = row[key]
        except Exception:
            val = None
        if val not in (None, ""):
            return val
    return ""


def _ft_insert_filtered(conn, table_name, data):
    cols = set(_ft_columns(conn, table_name))
    clean = {k: v for k, v in data.items() if k in cols}
    if not clean:
        return None
    keys = list(clean.keys())
    placeholders = ",".join(["?"] * len(keys))
    sql = f"INSERT INTO {table_name} ({','.join(keys)}) VALUES ({placeholders})"
    cur = conn.execute(sql, tuple(clean[k] for k in keys))
    return cur.lastrowid


def _ft_client_key(row):
    piva = _ft_norm_key(_ft_first(row, "partita_iva", "PartitaIVA", "piva"))
    cf = _ft_norm_key(_ft_first(row, "codice_fiscale", "CodiceFiscale", "cf"))
    den = _ft_norm_key(_ft_first(row, "denominazione", "Denominazione", "ragione_sociale"))
    return piva or cf or den


def _ft_collaborator_key(row):
    mail = _ft_norm_key(_ft_first(row, "mail", "email", "Mail"))
    nome = _ft_norm_key(_ft_first(row, "nome", "Nome"))
    cognome = _ft_norm_key(_ft_first(row, "cognome", "Cognome"))
    return mail or (nome + cognome)


def _ft_build_existing_clients(conn):
    existing = {}
    if not _ft_table_exists(conn, "clients"):
        return existing
    for r in conn.execute("SELECT * FROM clients").fetchall():
        key = _ft_client_key(r)
        if key:
            existing[key] = int(r["id"])
    return existing


def _ft_build_existing_collaborators(conn):
    existing = {}
    if not _ft_table_exists(conn, "collaborators"):
        return existing
    for r in conn.execute("SELECT * FROM collaborators").fetchall():
        key = _ft_collaborator_key(r)
        if key:
            existing[key] = int(r["id"])
    return existing


def _ft_merge_collaborators(src_conn, dst_conn):
    mapping = {}
    existing = _ft_build_existing_collaborators(dst_conn)
    source_tables = []
    if _ft_table_exists(src_conn, "collaborators"):
        source_tables.append("collaborators")
    if _ft_table_exists(src_conn, "collaboratori"):
        source_tables.append("collaboratori")
    for table in source_tables:
        for r in src_conn.execute(f"SELECT * FROM {table}").fetchall():
            old_id = int(_ft_first(r, "id", "Id") or 0)
            key = _ft_collaborator_key(r)
            if not key:
                continue
            if key in existing:
                mapping[old_id] = existing[key]
                continue
            if table == "collaborators":
                data = {
                    "nome": _ft_first(r, "nome") or "Collaboratore",
                    "cognome": _ft_first(r, "cognome") or "",
                    "cellulare": _ft_first(r, "cellulare", "telefono"),
                    "mail": _ft_first(r, "mail", "email"),
                    "created_at": _ft_first(r, "created_at") or _ft_now(),
                }
            else:
                nome_full = str(_ft_first(r, "nome") or "Collaboratore").strip()
                parts = nome_full.split(" ", 1)
                data = {
                    "nome": parts[0],
                    "cognome": parts[1] if len(parts) > 1 else "",
                    "cellulare": _ft_first(r, "telefono"),
                    "mail": _ft_first(r, "email"),
                    "created_at": _ft_first(r, "created_at") or _ft_now(),
                }
            new_id = _ft_insert_filtered(dst_conn, "collaborators", data)
            if new_id:
                mapping[old_id] = int(new_id)
                existing[key] = int(new_id)
    return mapping


def _ft_merge_clients(src_conn, dst_conn, collab_map):
    mapping = {}
    existing = _ft_build_existing_clients(dst_conn)
    source_tables = []
    if _ft_table_exists(src_conn, "clients"):
        source_tables.append("clients")
    if _ft_table_exists(src_conn, "Clienti"):
        source_tables.append("Clienti")
    if _ft_table_exists(src_conn, "clienti"):
        source_tables.append("clienti")
    for table in source_tables:
        for r in src_conn.execute(f"SELECT * FROM {table}").fetchall():
            old_id = int(_ft_first(r, "id", "Id") or 0)
            den = _ft_first(r, "denominazione", "Denominazione", "ragione_sociale") or f"Cliente importato {old_id}"
            key = _ft_client_key(r) or _ft_norm_key(den)
            if key in existing:
                mapping[old_id] = existing[key]
                continue
            if table == "clients":
                resp = _ft_first(r, "responsible_collaborator_id")
                data = {
                    "denominazione": den,
                    "partita_iva": _ft_first(r, "partita_iva"),
                    "codice_fiscale": _ft_first(r, "codice_fiscale"),
                    "sede_operativa": _ft_first(r, "sede_operativa"),
                    "sede_legale": _ft_first(r, "sede_legale"),
                    "anno_costituzione": _ft_first(r, "anno_costituzione"),
                    "amministratore": _ft_first(r, "amministratore"),
                    "settore_attivita": _ft_first(r, "settore_attivita"),
                    "mail_azienda": _ft_first(r, "mail_azienda", "email"),
                    "mail_amministratore": _ft_first(r, "mail_amministratore"),
                    "telefono_azienda": _ft_first(r, "telefono_azienda"),
                    "telefono_amministratore": _ft_first(r, "telefono_amministratore"),
                    "anagrafica_completa": _ft_first(r, "anagrafica_completa"),
                    "report_dati": _ft_first(r, "report_dati"),
                    "responsible_collaborator_id": collab_map.get(int(resp or 0), resp or None),
                    "note2": _ft_first(r, "note2", "note"),
                    "created_at": _ft_first(r, "created_at") or _ft_now(),
                }
            elif table == "Clienti":
                data = {
                    "denominazione": den,
                    "partita_iva": _ft_first(r, "PartitaIVA"),
                    "codice_fiscale": _ft_first(r, "CodiceFiscale"),
                    "sede_operativa": _ft_first(r, "SedeOperativa"),
                    "sede_legale": _ft_first(r, "SedeLegale"),
                    "anno_costituzione": _ft_first(r, "AnnoCostituzione"),
                    "amministratore": _ft_first(r, "Amministratore"),
                    "settore_attivita": _ft_first(r, "SettoreAttivita"),
                    "mail_azienda": _ft_first(r, "MailAzienda"),
                    "mail_amministratore": _ft_first(r, "MailAmministratore"),
                    "telefono_azienda": _ft_first(r, "TelAzienda"),
                    "telefono_amministratore": _ft_first(r, "TelAmministratore"),
                    "note2": _ft_first(r, "Note"),
                    "created_at": _ft_now(),
                }
            else:
                data = {
                    "denominazione": den,
                    "partita_iva": _ft_first(r, "piva"),
                    "codice_fiscale": _ft_first(r, "cf"),
                    "sede_legale": _ft_first(r, "indirizzo"),
                    "mail_azienda": _ft_first(r, "email"),
                    "telefono_azienda": _ft_first(r, "telefono"),
                    "note2": _ft_first(r, "note"),
                    "created_at": _ft_first(r, "created_at") or _ft_now(),
                }
            new_id = _ft_insert_filtered(dst_conn, "clients", data)
            if new_id:
                mapping[old_id] = int(new_id)
                existing[key] = int(new_id)
    return mapping


def _ft_document_exists(conn, client_id, title, filename, stored_path):
    try:
        row = conn.execute(
            """
            SELECT id FROM documents
            WHERE client_id = ?
              AND COALESCE(title,'') = COALESCE(?, '')
              AND COALESCE(original_filename,'') = COALESCE(?, '')
              AND COALESCE(stored_path,'') = COALESCE(?, '')
            LIMIT 1
            """,
            (client_id, title or "", filename or "", stored_path or ""),
        ).fetchone()
        return bool(row)
    except Exception:
        return False


def _ft_merge_documents(src_conn, dst_conn, client_map, collab_map):
    inserted = 0
    source_tables = []
    for table in ("documents", "Documenti", "documenti", "scoring_plus_documents"):
        if _ft_table_exists(src_conn, table):
            source_tables.append(table)
    for table in source_tables:
        for r in src_conn.execute(f"SELECT * FROM {table}").fetchall():
            old_client = int(_ft_first(r, "client_id", "ClienteId", "cliente_id") or 0)
            new_client = client_map.get(old_client)
            if not new_client:
                continue
            if table == "Documenti":
                category = _ft_first(r, "TipoDocumento") or "Documento importato"
                title = _ft_first(r, "NomeFile") or category
                filename = _ft_first(r, "NomeFile")
                stored = _ft_first(r, "PercorsoFile")
                uploaded = _ft_first(r, "DataCaricamento") or _ft_now()
                notes = "Importato da financeplus.db"
                collab_id = None
            elif table == "documenti":
                category = _ft_first(r, "categoria") or "Documento importato"
                title = _ft_first(r, "titolo") or category
                filename = Path(str(_ft_first(r, "file_path") or "")).name
                stored = _ft_first(r, "file_path")
                uploaded = _ft_first(r, "created_at") or _ft_now()
                notes = _ft_first(r, "testo_estratto")
                collab_id = None
            elif table == "scoring_plus_documents":
                category = _ft_first(r, "category") or "Scoring Plus"
                filename = _ft_first(r, "original_filename")
                title = filename or category
                stored = _ft_first(r, "stored_path")
                uploaded = _ft_first(r, "uploaded_at") or _ft_now()
                notes = (_ft_first(r, "notes") or "") + " [Scoring Plus]"
                collab_id = None
            else:
                category = _ft_first(r, "category") or _ft_first(r, "doc_kind") or "Documento"
                title = _ft_first(r, "title") or _ft_first(r, "original_filename") or category
                filename = _ft_first(r, "original_filename")
                stored = _ft_first(r, "stored_path")
                uploaded = _ft_first(r, "uploaded_at") or _ft_first(r, "created_at") or _ft_now()
                notes = _ft_first(r, "notes")
                old_collab = int(_ft_first(r, "collaborator_id") or 0)
                collab_id = collab_map.get(old_collab)
            if _ft_document_exists(dst_conn, new_client, title, filename, stored):
                continue
            _ft_insert_filtered(dst_conn, "documents", {
                "client_id": new_client,
                "collaborator_id": collab_id,
                "category": category,
                "title": title,
                "original_filename": filename,
                "stored_path": stored,
                "notes": notes,
                "uploaded_at": uploaded,
            })
            inserted += 1
    return inserted


def _ft_request_exists(conn, client_id, subject, rdate):
    try:
        row = conn.execute(
            "SELECT id FROM requests WHERE client_id=? AND COALESCE(request_subject,'')=COALESCE(?, '') AND COALESCE(request_date,'')=COALESCE(?, '') LIMIT 1",
            (client_id, subject or "", str(rdate or "")[:10]),
        ).fetchone()
        return bool(row)
    except Exception:
        return False


def _ft_merge_requests(src_conn, dst_conn, client_map, collab_map):
    if not _ft_table_exists(src_conn, "requests"):
        return 0
    inserted = 0
    for r in src_conn.execute("SELECT * FROM requests").fetchall():
        old_client = int(_ft_first(r, "client_id") or 0)
        new_client = client_map.get(old_client)
        if not new_client:
            continue
        subject = _ft_first(r, "request_subject", "subject", "request_object") or _ft_first(r, "notes") or "Richiesta importata"
        rdate = _ft_first(r, "request_date", "created_at") or _ft_now()[:10]
        if _ft_request_exists(dst_conn, new_client, subject, rdate):
            continue
        old_resp = int(_ft_first(r, "responsible_collaborator_id") or 0)
        _ft_insert_filtered(dst_conn, "requests", {
            "client_id": new_client,
            "request_date": str(rdate)[:10],
            "request_status": _ft_first(r, "request_status") or "Inevasa",
            "responsible_collaborator_id": collab_map.get(old_resp),
            "notes": _ft_first(r, "notes"),
            "contact_method": _ft_first(r, "contact_method"),
            "request_subject": subject,
            "status_detail": _ft_first(r, "status_detail"),
            "traffic_light": _ft_first(r, "traffic_light"),
            "importo_richiesta": _ft_first(r, "importo_richiesta"),
            "durata": _ft_first(r, "durata"),
            "istituto_fintech": _ft_first(r, "istituto_fintech"),
            "gestore": _ft_first(r, "gestore"),
            "data_presa_in_carico": _ft_first(r, "data_presa_in_carico"),
            "data_presentazione": _ft_first(r, "data_presentazione"),
            "created_at": _ft_first(r, "created_at") or _ft_now(),
        })
        inserted += 1
    return inserted


def _ft_merge_one_db(src_path, dst_path):
    if not Path(src_path).exists() or Path(src_path).resolve() == Path(dst_path).resolve():
        return "saltato"
    src = sqlite3.connect(src_path)
    dst = sqlite3.connect(dst_path)
    src.row_factory = sqlite3.Row
    dst.row_factory = sqlite3.Row
    try:
        collab_map = _ft_merge_collaborators(src, dst)
        client_map = _ft_merge_clients(src, dst, collab_map)
        doc_count = _ft_merge_documents(src, dst, client_map, collab_map)
        req_count = _ft_merge_requests(src, dst, client_map, collab_map)
        dst.commit()
        return f"clienti {len(client_map)}, collab {len(collab_map)}, documenti {doc_count}, richieste {req_count}"
    finally:
        src.close()
        dst.close()


def _ft_prepare_database_before_start():
    global _FULL_TOP_IMPORT_STATUS
    _FULL_TOP_IMPORT_STATUS = []
    try:
        app_dir = get_app_data_dir()
        app_dir.mkdir(parents=True, exist_ok=True)
        dst = app_dir / "gestione_clienti.db"
        src_dir = Path(__file__).resolve().parent
        candidates = [src_dir / name for name in FULL_TOP_DB_CANDIDATES if (src_dir / name).exists()]
        if not candidates:
            _FULL_TOP_IMPORT_STATUS.append("Nessun database esterno trovato accanto al file.")
        if dst.exists():
            backup_dir = app_dir / "backup_full_top"
            backup_dir.mkdir(parents=True, exist_ok=True)
            backup = backup_dir / ("gestione_clienti_prima_full_top_" + datetime.now().strftime("%Y%m%d_%H%M%S") + ".db")
            shutil.copy2(dst, backup)
            _FULL_TOP_IMPORT_STATUS.append(f"Backup creato: {backup.name}")
        else:
            # Se esiste gia un gestione_clienti.db accanto al programma, usalo come base.
            preferred = src_dir / "gestione_clienti.db"
            if preferred.exists():
                shutil.copy2(preferred, dst)
                _FULL_TOP_IMPORT_STATUS.append("Database base copiato da gestione_clienti.db.")
        # Garantisce schema moderno prima della fusione.
        tmp = Database(dst)
        try:
            tmp.conn.close()
        except Exception:
            pass
        for candidate in candidates:
            try:
                result = _ft_merge_one_db(candidate, dst)
                _FULL_TOP_IMPORT_STATUS.append(f"Import {candidate.name}: {result}")
            except Exception as exc:
                _FULL_TOP_IMPORT_STATUS.append(f"Errore import {candidate.name}: {exc}")
        try:
            log = app_dir / "full_top_import_log.txt"
            log.write_text("\n".join([_ft_now()] + _FULL_TOP_IMPORT_STATUS), encoding="utf-8")
        except Exception:
            pass
    except Exception as exc:
        _FULL_TOP_IMPORT_STATUS.append(f"Errore preparazione DB: {exc}")


# Estende i documenti mostrati nella dashboard e nella scheda cliente 360 includendo scoring_plus_documents.
try:
    _FULL_TOP_ORIG_M2_LIST_DOCS = _m2_list_docs
    def _m2_list_docs(db, client_id):
        rows = []
        seen = set()
        try:
            base_rows = list(_FULL_TOP_ORIG_M2_LIST_DOCS(db, client_id) or [])
        except Exception:
            base_rows = []
        for r in base_rows:
            key = (str(_ft_first(r, "stored_path")), str(_ft_first(r, "original_filename")), str(_ft_first(r, "category")))
            rows.append(r)
            seen.add(key)
        try:
            if _ft_table_exists(db.conn, "scoring_plus_documents"):
                for r in db.conn.execute("SELECT * FROM scoring_plus_documents WHERE client_id = ? ORDER BY uploaded_at DESC, id DESC", (client_id,)).fetchall():
                    key = (str(_ft_first(r, "stored_path")), str(_ft_first(r, "original_filename")), str(_ft_first(r, "category")))
                    if key not in seen:
                        rows.append(r)
                        seen.add(key)
        except Exception:
            pass
        return rows
except Exception:
    pass

try:
    _FULL_TOP_ORIG_C360_LIST_DOCUMENTS = _c360_list_documents
    def _c360_list_documents(db, client_id: int):
        rows = []
        seen = set()
        try:
            base_rows = list(_FULL_TOP_ORIG_C360_LIST_DOCUMENTS(db, client_id) or [])
        except Exception:
            base_rows = []
        for r in base_rows:
            key = (str(_ft_first(r, "stored_path")), str(_ft_first(r, "original_filename")), str(_ft_first(r, "category")))
            rows.append(r)
            seen.add(key)
        try:
            if _ft_table_exists(db.conn, "scoring_plus_documents"):
                for r in db.conn.execute("SELECT * FROM scoring_plus_documents WHERE client_id = ? ORDER BY uploaded_at DESC, id DESC", (client_id,)).fetchall():
                    key = (str(_ft_first(r, "stored_path")), str(_ft_first(r, "original_filename")), str(_ft_first(r, "category")))
                    if key not in seen:
                        rows.append(r)
                        seen.add(key)
        except Exception:
            pass
        return rows
except Exception:
    pass


# Stampa collaboratore versione estesa: include clienti assegnati e clienti collegati da richieste/documenti.
def _m2_collaborator_report_data(db, collaborator_id):
    try:
        cid_int = int(collaborator_id)
    except Exception:
        cid_int = 0
    clients_all = list(db.list_clients("") or [])
    client_ids = set()
    for c in clients_all:
        try:
            if int(_m2_get(c, "responsible_collaborator_id") or 0) == cid_int:
                client_ids.add(int(_m2_get(c, "id")))
        except Exception:
            pass
    try:
        if _ft_table_exists(db.conn, "requests"):
            for r in db.conn.execute("SELECT DISTINCT client_id FROM requests WHERE responsible_collaborator_id = ?", (cid_int,)).fetchall():
                client_ids.add(int(r["client_id"]))
    except Exception:
        pass
    try:
        if _ft_table_exists(db.conn, "documents") and "collaborator_id" in _ft_columns(db.conn, "documents"):
            for r in db.conn.execute("SELECT DISTINCT client_id FROM documents WHERE collaborator_id = ?", (cid_int,)).fetchall():
                client_ids.add(int(r["client_id"]))
    except Exception:
        pass
    clients = [c for c in clients_all if int(_m2_get(c, "id") or 0) in client_ids]

    client_rows = []
    doc_rows = []
    req_rows = []
    for client in clients:
        client_id = int(_m2_get(client, "id"))
        cname = _m2_get(client, "denominazione") or f"Cliente {client_id}"
        checklist = _m2_checklist(db, client_id)
        requests = _m2_list_reqs(db, client_id)
        status, reason = _m2_client_operational_status(checklist, requests)
        docs = _m2_list_docs(db, client_id)
        open_requests = [r for r in requests if _m2_request_open(r)]
        client_rows.append({
            "cliente": cname,
            "stato": status,
            "documenti_ricevuti": len(docs),
            "richieste_inevase": len(open_requests),
            "criticita": reason,
        })
        for d in docs:
            # Per clienti assegnati stampa tutti i documenti ricevuti; per clienti solo collegati stampa comunque i doc collegati.
            doc_collab = _m2_get(d, "collaborator_id")
            assigned = int(_m2_get(client, "responsible_collaborator_id") or 0) == cid_int
            if assigned or str(doc_collab or "") == str(cid_int) or doc_collab in (None, ""):
                doc_rows.append({
                    "cliente": cname,
                    "titolo": _m2_get(d, "title") or _m2_get(d, "original_filename") or "Documento",
                    "categoria": _m2_get(d, "category") or "",
                    "data": str(_m2_uploaded_date(d) or "")[:10],
                    "caricato_da": _m2_responsible_name(db, client),
                })
        for r in open_requests:
            resp_id = _m2_get(r, "responsible_collaborator_id")
            assigned = int(_m2_get(client, "responsible_collaborator_id") or 0) == cid_int
            if assigned or str(resp_id or "") == str(cid_int) or resp_id in (None, ""):
                days = _m2_request_days(r)
                req_rows.append({
                    "cliente": cname,
                    "oggetto": _m2_get(r, "request_subject") or _m2_get(r, "notes") or "Richiesta senza oggetto",
                    "data": str(_m2_get(r, "request_date") or _m2_get(r, "created_at") or "")[:10],
                    "giorni": "" if days is None else str(days),
                    "stato": _m2_get(r, "request_status") or "Inevasa",
                    "note": _m2_get(r, "status_detail") or _m2_get(r, "notes") or "",
                })
    totals = {
        "Clienti assegnati/collegati": len(client_rows),
        "Documenti ricevuti": len(doc_rows),
        "Richieste inevase": len(req_rows),
        "Pratiche bloccate": len([r for r in client_rows if r["stato"] == "BLOCCATA"]),
        "Pratiche parziali": len([r for r in client_rows if r["stato"] == "PARZIALE"]),
        "Pratiche da inviare": len([r for r in client_rows if r["stato"] == "DA INVIARE"]),
    }
    return client_rows, doc_rows, req_rows, totals


# Wrapper avvio: prepara il database integrato prima di creare l'interfaccia.
try:
    _FULL_TOP_ORIG_MAIN_INIT = MainApplication.__init__
    def _full_top_main_init(self):
        _ft_prepare_database_before_start()
        _FULL_TOP_ORIG_MAIN_INIT(self)
        try:
            if hasattr(self, "banner_status"):
                self.banner_status.configure(text="FULL TOP\nDB INTEGRATI")
        except Exception:
            pass
        try:
            self.title(f"{APP_TITLE} v{APP_VERSION} - FULL TOP INTEGRATO")
        except Exception:
            pass
    MainApplication.__init__ = _full_top_main_init
except Exception:
    pass

