def _top_assoluto_dir() -> Path:
    try:
        base = get_app_data_dir() / "top_assoluto_assets"
    except Exception:
        base = Path.home() / ".financeplus_top_assoluto" / "top_assoluto_assets"
    base.mkdir(parents=True, exist_ok=True)
    return base


def _top_assoluto_asset_path(name: str) -> Path:
    return _top_assoluto_dir() / name


def _top_assoluto_write_asset(name: str, force: bool = False) -> Path:
    info = _TOP_ASSOLUTO_ASSETS[name]
    out = _top_assoluto_asset_path(name)
    if out.exists() and not force:
        try:
            if _top_hashlib.sha256(out.read_bytes()).hexdigest() == info["sha256"]:
                return out
        except Exception:
            pass
    raw = _top_zlib.decompress(base64.b64decode(info["b64z"].encode("ascii")))
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(raw)
    return out


def _top_assoluto_extract_all(force: bool = False) -> Path:
    folder = _top_assoluto_dir()
    for name in _TOP_ASSOLUTO_ASSETS:
        _top_assoluto_write_asset(name, force=force)
    try:
        (folder / "LEGGIMI_TOP_ASSOLUTO.txt").write_text(
            "FinancePlus TOP ASSOLUTO UNIFICATO\n\n"
            "Questo pacchetto e' generato da un solo file Python.\n"
            "L'app principale e' il Gestionale Clienti 360 FULL TOP.\n"
            "Dal menu TOP ASSOLUTO puoi aprire simulatore di finanziabilita, Finance Atena, template e modulo legacy.\n\n"
            "Nota: gli scoring sono simulazioni prudenziali e non modelli proprietari bancari.\n",
            encoding="utf-8",
        )
    except Exception:
        pass
    return folder


def _top_assoluto_seed_database() -> None:
    """Copia il DB seed incorporato solo se non esiste gia' il database operativo."""
    try:
        seed = _top_assoluto_write_asset("gestione_clienti_seed.db")
        dst = get_app_data_dir() / "gestione_clienti.db"
        if not dst.exists() and seed.exists():
            shutil.copy2(seed, dst)
        # rende disponibile il seed anche con nome standard per la routine FULL_TOP_IMPORT
        standard = _top_assoluto_dir() / "gestione_clienti.db"
        if not standard.exists() and seed.exists():
            shutil.copy2(seed, standard)
    except Exception:
        pass


def _top_assoluto_open_folder(path: Path) -> None:
    try:
        open_path(str(path))
    except Exception:
        try:
            if sys.platform.startswith("win"):
                os.startfile(str(path))  # type: ignore[attr-defined]
            elif sys.platform == "darwin":
                subprocess.Popen(["open", str(path)])
            else:
                subprocess.Popen(["xdg-open", str(path)])
        except Exception as exc:
            try:
                messagebox.showerror("Apertura cartella", f"Impossibile aprire la cartella:\n{path}\n\n{exc}")
            except Exception:
                print(f"Impossibile aprire {path}: {exc}")


def _top_assoluto_launch(asset_name: str, args: _TopOptional[list[str]] = None) -> None:
    try:
        _top_assoluto_extract_all(force=False)
        script = _top_assoluto_write_asset(asset_name)
        cmd = [sys.executable, str(script)] + list(args or [])
        subprocess.Popen(cmd, cwd=str(script.parent))
    except Exception as exc:
        try:
            messagebox.showerror("TOP ASSOLUTO", f"Impossibile avviare {asset_name}:\n{exc}")
        except Exception:
            print(f"Errore avvio {asset_name}: {exc}")


def _top_assoluto_export_templates() -> None:
    try:
        folder = _top_assoluto_extract_all(force=False)
        _top_assoluto_open_folder(folder)
        messagebox.showinfo(
            "Template estratti",
            "Ho estratto template Excel, database seed e moduli nella cartella TOP ASSOLUTO."
        )
    except Exception as exc:
        try:
            messagebox.showerror("Template", str(exc))
        except Exception:
            print(exc)


def _top_assoluto_healthcheck() -> str:
    lines = [f"{TOP_ASSOLUTO_APP_NAME} - versione {TOP_ASSOLUTO_VERSION}"]
    folder = _top_assoluto_extract_all(force=False)
    lines.append(f"Cartella asset: {folder}")
    for name, info in _TOP_ASSOLUTO_ASSETS.items():
        p = folder / name
        ok = p.exists() and _top_hashlib.sha256(p.read_bytes()).hexdigest() == info["sha256"]
        lines.append(f"{'OK' if ok else 'ERRORE'} - {name} ({info['size']} byte)")
    lines.append("\nDipendenze consigliate: pandas, openpyxl, pypdf, pillow, reportlab, pdfplumber.")
    return "\n".join(lines)


def _top_assoluto_show_healthcheck() -> None:
    try:
        win = tk.Toplevel()
        win.title("TOP ASSOLUTO - Diagnostica")
        win.geometry("880x560")
        txt = ScrolledText(win, wrap="word")
        txt.pack(fill="both", expand=True, padx=12, pady=12)
        txt.insert("1.0", _top_assoluto_healthcheck())
        txt.configure(state="disabled")
    except Exception:
        print(_top_assoluto_healthcheck())


def _top_assoluto_add_menu(self) -> None:
    try:
        try:
            current = self.cget("menu")
            menubar = self.nametowidget(current) if current else tk.Menu(self)
        except Exception:
            menubar = tk.Menu(self)

        suite_menu = tk.Menu(menubar, tearoff=0)
        suite_menu.add_command(
            label="Simulatore finanziabilita bancaria TOP",
            command=lambda: _top_assoluto_launch("simulatore_finanziabilita_bancaria.py"),
        )
        suite_menu.add_command(
            label="Simulatore credito parametrico MCC/CR/DSCR",
            command=lambda: _top_assoluto_launch("simulatore_finanziabilita_credito.py", ["--gui"]),
        )
        suite_menu.add_command(
            label="Finance Atena - business plan e scenari",
            command=lambda: _top_assoluto_launch("finance_atena.py"),
        )
        suite_menu.add_separator()
        suite_menu.add_command(
            label="Modulo legacy v42 AideXa/MCC/Flussi C/C",
            command=lambda: _top_assoluto_launch("app_v42_con_moduli_aidexa_mcc_flussi_cc.py"),
        )
        suite_menu.add_separator()
        suite_menu.add_command(label="Estrai template Excel + DB seed", command=_top_assoluto_export_templates)
        suite_menu.add_command(label="Apri cartella TOP ASSOLUTO", command=lambda: _top_assoluto_open_folder(_top_assoluto_dir()))
        suite_menu.add_command(label="Diagnostica pacchetto", command=_top_assoluto_show_healthcheck)

        menubar.add_cascade(label="TOP ASSOLUTO", menu=suite_menu)
        self.config(menu=menubar)
    except Exception as exc:
        try:
            messagebox.showwarning("TOP ASSOLUTO", f"Menu TOP non inizializzato: {exc}")
        except Exception:
            print(f"Menu TOP non inizializzato: {exc}")


try:
    _TOP_ASSOLUTO_ORIG_MAIN_INIT = MainApplication.__init__
    def _top_assoluto_main_init(self):
        _top_assoluto_extract_all(force=False)
        _top_assoluto_seed_database()
        _TOP_ASSOLUTO_ORIG_MAIN_INIT(self)
        try:
            _top_assoluto_add_menu(self)
        except Exception:
            pass
        try:
            self.title(f"{APP_TITLE} v{APP_VERSION} - TOP ASSOLUTO UNIFICATO")
        except Exception:
            pass
        try:
            if hasattr(self, "banner_status"):
                self.banner_status.configure(text="TOP\nASSOLUTO")
        except Exception:
            pass
    MainApplication.__init__ = _top_assoluto_main_init
except Exception:
    pass

