# === PATCH REPORT COLLABORATORE PDF STAMPABILE ===
# Aggiunge un pulsante "Report collaboratore PDF" nell'elenco collaboratori,
# nella scheda collaboratore e nella dashboard operativa. Il report riepiloga:
# - collaboratore selezionato;
# - aziende/clienti associate;
# - gestione cliente e stato pratica;
# - documenti presenti per ogni azienda;
# - richieste aperte e note operative.


def _fpcr_row_get(row, key, default=""):
    try:
        if row is None:
            return default
        if hasattr(row, "keys"):
            if key in row.keys():
                value = row[key]
                return default if value is None else value
            return default
        if isinstance(row, dict):
            value = row.get(key, default)
            return default if value is None else value
        value = getattr(row, key, default)
        return default if value is None else value
    except Exception:
        return default


def _fpcr_short(value, limit=140):
    txt = str(value or "").replace("\r", " ").replace("\n", " ").strip()
    txt = re.sub(r"\s+", " ", txt)
    if len(txt) > limit:
        return txt[:max(0, limit - 3)] + "..."
    return txt


def _fpcr_safe_filename(value):
    txt = str(value or "report").strip().lower()
    txt = re.sub(r"[^a-z0-9]+", "_", txt)
    txt = re.sub(r"_+", "_", txt).strip("_")
    return txt or "report"


def _fpcr_table_exists(conn, table_name):
    try:
        row = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table_name,)).fetchone()
        return bool(row)
    except Exception:
        return False


def _fpcr_columns(conn, table_name):
    try:
        return {str(r[1]) for r in conn.execute(f"PRAGMA table_info({table_name})").fetchall()}
    except Exception:
        return set()


def _fpcr_para(value, style):
    try:
        return Paragraph(html.escape(str(value or "")), style)
    except Exception:
        safe = str(value or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        return Paragraph(safe, style)


def _fpcr_collaborator_name(collab):
    name = (str(_fpcr_row_get(collab, "nome", "")).strip() + " " + str(_fpcr_row_get(collab, "cognome", "")).strip()).strip()
    return name or "Collaboratore"


def _fpcr_client_display_name(client):
    return str(_fpcr_row_get(client, "denominazione", "")).strip() or f"Cliente {str(_fpcr_row_get(client, 'id', '')).strip()}"


def _fpcr_list_related_clients(db, collaborator_id):
    """Clienti/aziende assegnati o collegati al collaboratore da clienti, richieste, documenti."""
    rows = []
    seen = set()
    try:
        for row in db.get_related_clients_for_collaborator(collaborator_id) or []:
            rid = int(_fpcr_row_get(row, "id", 0) or 0)
            if rid and rid not in seen:
                rows.append(row)
                seen.add(rid)
    except Exception:
        pass

    # Fallback/integrazione robusta: clienti assegnati.
    try:
        for row in db.list_clients("") or []:
            rid = int(_fpcr_row_get(row, "id", 0) or 0)
            resp = int(_fpcr_row_get(row, "responsible_collaborator_id", 0) or 0)
            if rid and resp == int(collaborator_id) and rid not in seen:
                rows.append(row)
                seen.add(rid)
    except Exception:
        pass

    # Include eventuali collegamenti da scoring_plus_documents se presenti.
    try:
        if _fpcr_table_exists(db.conn, "scoring_plus_documents"):
            cols = _fpcr_columns(db.conn, "scoring_plus_documents")
            if "client_id" in cols and "collaborator_id" in cols:
                for r in db.conn.execute("SELECT DISTINCT client_id FROM scoring_plus_documents WHERE collaborator_id = ?", (collaborator_id,)).fetchall():
                    cid = int(_fpcr_row_get(r, "client_id", 0) or 0)
                    if cid and cid not in seen:
                        client = db.get_client(cid)
                        if client:
                            rows.append(client)
                            seen.add(cid)
    except Exception:
        pass

    rows.sort(key=lambda x: _fpcr_client_display_name(x).lower())
    return rows


def _fpcr_list_client_documents(db, client_id):
    """Elenco documenti per cliente, includendo archivio documenti e scoring plus se presente."""
    rows = []
    seen = set()
    def add_row(row, source="Documenti"):
        rid = str(_fpcr_row_get(row, "id", ""))
        title = str(_fpcr_row_get(row, "title", "") or _fpcr_row_get(row, "original_filename", ""))
        path = str(_fpcr_row_get(row, "stored_path", ""))
        key = (source, rid, title, path)
        if key in seen:
            return
        seen.add(key)
        rows.append((row, source))

    try:
        list_fn = getattr(db, "list_documents_linked", None) or getattr(db, "list_documents", None)
        for d in list_fn(client_id) or []:
            add_row(d, "Archivio documenti")
    except Exception:
        try:
            for d in db.list_documents(client_id) or []:
                add_row(d, "Archivio documenti")
        except Exception:
            pass

    try:
        if _fpcr_table_exists(db.conn, "scoring_plus_documents"):
            cols = _fpcr_columns(db.conn, "scoring_plus_documents")
            if "client_id" in cols:
                order = ""
                if "uploaded_at" in cols:
                    order = " ORDER BY uploaded_at DESC"
                elif "created_at" in cols:
                    order = " ORDER BY created_at DESC"
                for d in db.conn.execute("SELECT * FROM scoring_plus_documents WHERE client_id = ?" + order, (client_id,)).fetchall():
                    add_row(d, "Scoring Plus")
    except Exception:
        pass
    return rows


def _fpcr_list_client_requests(db, client_id):
    try:
        return list(db.list_requests(client_id) or [])
    except Exception:
        return []


def _fpcr_client_status(db, client_id):
    try:
        checklist = _m2_checklist(db, client_id)
        requests = _m2_list_reqs(db, client_id)
        return _m2_client_operational_status(checklist, requests)
    except Exception:
        return ("DA VERIFICARE", "Controllare documenti e richieste associate")


def _fpcr_client_info_rows(db, client_id):
    try:
        info = db.get_client_info(client_id)
    except Exception:
        info = None
    if not info:
        return []
    fields = [
        ("Importo richiesta", "importo_richiesta"),
        ("Durata", "durata"),
        ("Istituto/Fintech", "istituto_fintech"),
        ("Gestore", "gestore"),
        ("Data presa in carico", "data_presa_in_carico"),
        ("Data presentazione", "data_presentazione"),
        ("Tipologia prodotto", "tipologia_prodotto"),
        ("Info aggiuntive", "informazioni_aggiuntive"),
    ]
    out = []
    for label, key in fields:
        val = _fpcr_short(_fpcr_row_get(info, key, ""), 160)
        if val:
            out.append((label, val))
    return out


def _fpcr_generate_collaborator_report_pdf(db, collaborator_id, parent=None):
    collab = db.get_collaborator(collaborator_id)
    if not collab:
        messagebox.showerror("Report collaboratore", "Collaboratore non trovato.")
        return None

    clients = _fpcr_list_related_clients(db, collaborator_id)
    collab_name = _fpcr_collaborator_name(collab)
    folder = get_app_data_dir() / "report_collaboratori"
    folder.mkdir(parents=True, exist_ok=True)
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    pdf_path = folder / f"report_collaboratore_{_fpcr_safe_filename(collab_name)}_{ts}.pdf"
    txt_path = folder / f"report_collaboratore_{_fpcr_safe_filename(collab_name)}_{ts}.txt"

    # Precalcolo dati per TXT e PDF.
    client_blocks = []
    total_docs = 0
    total_requests_open = 0
    status_counts = {"BLOCCATA": 0, "PARZIALE": 0, "DA INVIARE": 0, "OK": 0, "DA VERIFICARE": 0}
    for client in clients:
        client_id = int(_fpcr_row_get(client, "id", 0) or 0)
        docs = _fpcr_list_client_documents(db, client_id)
        reqs = _fpcr_list_client_requests(db, client_id)
        open_reqs = [r for r in reqs if (_m2_request_open(r) if "_m2_request_open" in globals() else str(_fpcr_row_get(r, "request_status", "")).upper() not in ("COMPLETATA", "COMPLETO", "CHIUSA", "CHIUSO"))]
        status, reason = _fpcr_client_status(db, client_id)
        status_counts[status] = status_counts.get(status, 0) + 1
        total_docs += len(docs)
        total_requests_open += len(open_reqs)
        client_blocks.append({
            "client": client,
            "client_id": client_id,
            "docs": docs,
            "requests": reqs,
            "open_requests": open_reqs,
            "status": status,
            "reason": reason,
            "info_rows": _fpcr_client_info_rows(db, client_id),
        })

    lines = []
    lines.append("REPORT COLLABORATORE")
    lines.append("Collaboratore: " + collab_name)
    lines.append("Data stampa: " + datetime.now().strftime("%d/%m/%Y %H:%M"))
    lines.append("Email: " + str(_fpcr_row_get(collab, "mail", "")))
    lines.append("Cellulare: " + str(_fpcr_row_get(collab, "cellulare", "")))
    lines.append("")
    lines.append("RIEPILOGO")
    lines.append(f"- Aziende associate: {len(clients)}")
    lines.append(f"- Documenti complessivi: {total_docs}")
    lines.append(f"- Richieste aperte/inevase: {total_requests_open}")
    lines.append(f"- Pratiche bloccate: {status_counts.get('BLOCCATA', 0)}")
    lines.append(f"- Pratiche parziali: {status_counts.get('PARZIALE', 0)}")
    lines.append(f"- Pratiche da inviare: {status_counts.get('DA INVIARE', 0)}")
    lines.append("")
    lines.append("AZIENDE ASSOCIATE")
    for block in client_blocks:
        c = block["client"]
        lines.append(f"- {_fpcr_client_display_name(c)} | P.IVA {_fpcr_row_get(c, 'partita_iva', '')} | Stato {block['status']} | Doc {len(block['docs'])} | Richieste aperte {len(block['open_requests'])}")
    lines.append("")
    lines.append("DETTAGLIO PER AZIENDA")
    for block in client_blocks:
        c = block["client"]
        lines.append("")
        lines.append("=" * 80)
        lines.append(_fpcr_client_display_name(c))
        lines.append(f"P.IVA: {_fpcr_row_get(c, 'partita_iva', '')} | CF: {_fpcr_row_get(c, 'codice_fiscale', '')}")
        lines.append(f"Sede operativa: {_fpcr_row_get(c, 'sede_operativa', '')}")
        lines.append(f"Amministratore: {_fpcr_row_get(c, 'amministratore', '')} | Settore: {_fpcr_row_get(c, 'settore_attivita', '')}")
        lines.append(f"Stato gestione: {block['status']} - {block['reason']}")
        lines.append("Documenti:")
        if block["docs"]:
            for d, source in block["docs"]:
                lines.append(f"  - [{source}] {_fpcr_row_get(d, 'category', '')} | {_fpcr_row_get(d, 'title', '') or _fpcr_row_get(d, 'original_filename', '')} | {_fpcr_row_get(d, 'uploaded_at', '') or _fpcr_row_get(d, 'created_at', '')}")
        else:
            lines.append("  - Nessun documento presente")
        lines.append("Richieste:")
        if block["requests"]:
            for r in block["requests"]:
                lines.append(f"  - {_fpcr_row_get(r, 'request_date', '')} | {_fpcr_row_get(r, 'request_subject', '') or _fpcr_row_get(r, 'notes', '')} | {_fpcr_row_get(r, 'request_status', '')}")
        else:
            lines.append("  - Nessuna richiesta presente")
    txt_path.write_text("\n".join(lines), encoding="utf-8")

    if not REPORTLAB_AVAILABLE:
        if messagebox.askyesno("Report collaboratore", f"Report TXT creato:\n{txt_path}\n\nReportLab non disponibile. Vuoi aprirlo?"):
            open_path(str(txt_path))
        return txt_path

    try:
        doc = SimpleDocTemplate(str(pdf_path), pagesize=A4, rightMargin=26, leftMargin=26, topMargin=28, bottomMargin=28)
        styles = getSampleStyleSheet()
        title = ParagraphStyle("FPCRTitle", parent=styles["Title"], fontSize=17, leading=21, spaceAfter=8)
        h2 = ParagraphStyle("FPCRH2", parent=styles["Heading2"], fontSize=12, leading=15, spaceBefore=9, spaceAfter=5, textColor=colors.HexColor("#17365D"))
        h3 = ParagraphStyle("FPCRH3", parent=styles["Heading3"], fontSize=10.5, leading=13, spaceBefore=8, spaceAfter=4, textColor=colors.HexColor("#17365D"))
        normal = ParagraphStyle("FPCRNormal", parent=styles["Normal"], fontSize=8.2, leading=10.3)
        small = ParagraphStyle("FPCRSmall", parent=styles["Normal"], fontSize=7.2, leading=8.7)
        small_bold = ParagraphStyle("FPCRSmallBold", parent=small, fontName="Helvetica-Bold")

        def tbl(data, widths, header=True, font_size=7.2):
            t = Table(data, colWidths=widths, repeatRows=1 if header else 0)
            style = [
                ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#B9C2D0")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("FONTSIZE", (0, 0), (-1, -1), font_size),
                ("LEFTPADDING", (0, 0), (-1, -1), 3),
                ("RIGHTPADDING", (0, 0), (-1, -1), 3),
                ("TOPPADDING", (0, 0), (-1, -1), 2),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 2),
            ]
            if header:
                style += [
                    ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#17365D")),
                    ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                    ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                ]
            t.setStyle(TableStyle(style))
            return t

        story = []
        story.append(Paragraph("Report collaboratore - scheda completa clienti", title))
        story.append(Paragraph(f"Collaboratore: <b>{html.escape(collab_name)}</b>", normal))
        story.append(Paragraph("Data stampa: " + datetime.now().strftime("%d/%m/%Y %H:%M"), normal))
        story.append(Paragraph("File TXT completo: " + html.escape(str(txt_path.name)), small))
        story.append(Spacer(1, 7))

        # Anagrafica collaboratore.
        story.append(Paragraph("1. Dati collaboratore", h2))
        collab_data = [
            [_fpcr_para("Campo", small_bold), _fpcr_para("Valore", small_bold)],
            [_fpcr_para("Nome e cognome", small), _fpcr_para(collab_name, small)],
            [_fpcr_para("Cellulare", small), _fpcr_para(_fpcr_row_get(collab, "cellulare", ""), small)],
            [_fpcr_para("Email", small), _fpcr_para(_fpcr_row_get(collab, "mail", ""), small)],
        ]
        story.append(tbl(collab_data, [4.0*cm, 13.0*cm], header=True))
        story.append(Spacer(1, 8))

        # KPI.
        story.append(Paragraph("2. Riepilogo gestione", h2))
        kpi_data = [
            ["Indicatore", "Valore"],
            ["Aziende associate", str(len(clients))],
            ["Documenti complessivi", str(total_docs)],
            ["Richieste aperte/inevase", str(total_requests_open)],
            ["Pratiche bloccate", str(status_counts.get("BLOCCATA", 0))],
            ["Pratiche parziali", str(status_counts.get("PARZIALE", 0))],
            ["Pratiche da inviare", str(status_counts.get("DA INVIARE", 0))],
        ]
        story.append(tbl(kpi_data, [11.0*cm, 3.0*cm], header=True, font_size=8))
        story.append(Spacer(1, 8))

        # Elenco aziende.
        story.append(Paragraph("3. Elenco aziende associate", h2))
        if client_blocks:
            data = [["Azienda", "P.IVA / CF", "Stato", "Doc.", "Rich. aperte", "Criticita / note"]]
            for block in client_blocks:
                c = block["client"]
                data.append([
                    _fpcr_para(_fpcr_short(_fpcr_client_display_name(c), 45), small),
                    _fpcr_para(_fpcr_short((str(_fpcr_row_get(c, "partita_iva", "")) + " / " + str(_fpcr_row_get(c, "codice_fiscale", ""))).strip(" /"), 35), small),
                    _fpcr_para(block["status"], small),
                    str(len(block["docs"])),
                    str(len(block["open_requests"])),
                    _fpcr_para(_fpcr_short(block["reason"], 95), small),
                ])
            story.append(tbl(data, [4.3*cm, 3.0*cm, 2.1*cm, 1.0*cm, 1.6*cm, 5.0*cm], header=True))
        else:
            story.append(Paragraph("Nessuna azienda associata al collaboratore selezionato.", normal))

        story.append(PageBreak())
        story.append(Paragraph("4. Schede aziende e documenti", h2))

        for idx, block in enumerate(client_blocks, start=1):
            c = block["client"]
            cname = _fpcr_client_display_name(c)
            story.append(Paragraph(f"{idx}. {html.escape(cname)}", h3))

            client_summary = [
                ["Campo", "Valore", "Campo", "Valore"],
                ["Partita IVA", _fpcr_para(_fpcr_row_get(c, "partita_iva", ""), small), "Codice fiscale", _fpcr_para(_fpcr_row_get(c, "codice_fiscale", ""), small)],
                ["Sede operativa", _fpcr_para(_fpcr_short(_fpcr_row_get(c, "sede_operativa", ""), 90), small), "Sede legale", _fpcr_para(_fpcr_short(_fpcr_row_get(c, "sede_legale", ""), 90), small)],
                ["Amministratore", _fpcr_para(_fpcr_short(_fpcr_row_get(c, "amministratore", ""), 80), small), "Settore", _fpcr_para(_fpcr_short(_fpcr_row_get(c, "settore_attivita", ""), 80), small)],
                ["Email azienda", _fpcr_para(_fpcr_short(_fpcr_row_get(c, "mail_azienda", ""), 80), small), "Telefono", _fpcr_para(_fpcr_short(_fpcr_row_get(c, "telefono_azienda", ""), 40), small)],
                ["Stato gestione", _fpcr_para(block["status"], small), "Motivo", _fpcr_para(_fpcr_short(block["reason"], 120), small)],
            ]
            story.append(tbl(client_summary, [2.5*cm, 5.8*cm, 2.5*cm, 6.2*cm], header=True))

            if block["info_rows"]:
                story.append(Paragraph("Dati pratica / gestione cliente", h3))
                info_data = [["Voce", "Dato"]]
                for label, val in block["info_rows"]:
                    info_data.append([_fpcr_para(label, small), _fpcr_para(val, small)])
                story.append(tbl(info_data, [4.3*cm, 12.7*cm], header=True))

            story.append(Paragraph("Documenti presenti per azienda", h3))
            if block["docs"]:
                data = [["Fonte", "Categoria", "Titolo / file", "Data", "Note"]]
                for d, source in block["docs"]:
                    title_doc = _fpcr_row_get(d, "title", "") or _fpcr_row_get(d, "original_filename", "") or _fpcr_row_get(d, "filename", "") or "Documento"
                    date_doc = _fpcr_row_get(d, "uploaded_at", "") or _fpcr_row_get(d, "created_at", "") or _fpcr_row_get(d, "updated_at", "")
                    data.append([
                        _fpcr_para(source, small),
                        _fpcr_para(_fpcr_short(_fpcr_row_get(d, "category", "Altro"), 28), small),
                        _fpcr_para(_fpcr_short(title_doc, 80), small),
                        _fpcr_para(str(date_doc)[:10], small),
                        _fpcr_para(_fpcr_short(_fpcr_row_get(d, "notes", ""), 70), small),
                    ])
                story.append(tbl(data, [2.4*cm, 3.0*cm, 6.4*cm, 1.7*cm, 3.5*cm], header=True))
            else:
                story.append(Paragraph("Nessun documento presente per questa azienda.", normal))

            story.append(Paragraph("Richieste e attivita aperte/registrate", h3))
            if block["requests"]:
                data = [["Data", "Oggetto", "Stato", "Semaforo", "Note"]]
                for r in block["requests"]:
                    data.append([
                        _fpcr_para(str(_fpcr_row_get(r, "request_date", "") or _fpcr_row_get(r, "created_at", ""))[:10], small),
                        _fpcr_para(_fpcr_short(_fpcr_row_get(r, "request_subject", "") or _fpcr_row_get(r, "notes", ""), 70), small),
                        _fpcr_para(_fpcr_short(_fpcr_row_get(r, "request_status", "") or _fpcr_row_get(r, "status_detail", ""), 35), small),
                        _fpcr_para(_fpcr_short(_fpcr_row_get(r, "traffic_light", ""), 25), small),
                        _fpcr_para(_fpcr_short(_fpcr_row_get(r, "notes", ""), 75), small),
                    ])
                story.append(tbl(data, [1.9*cm, 5.8*cm, 3.0*cm, 2.0*cm, 4.3*cm], header=True))
            else:
                story.append(Paragraph("Nessuna richiesta registrata per questa azienda.", normal))

            extra_notes = []
            for k in ("note2", "report_dati", "anagrafica_completa"):
                val = _fpcr_short(_fpcr_row_get(c, k, ""), 500)
                if val:
                    extra_notes.append((k, val))
            if extra_notes:
                story.append(Paragraph("Note e riepilogo cliente", h3))
                note_data = [["Sezione", "Contenuto"]]
                for label, val in extra_notes:
                    note_data.append([_fpcr_para(label, small), _fpcr_para(val, small)])
                story.append(tbl(note_data, [3.0*cm, 14.0*cm], header=True))

            story.append(Spacer(1, 8))
            if idx < len(client_blocks):
                story.append(Spacer(1, 4))

        build_branded_pdf(doc, story, "Report collaboratore")
        if messagebox.askyesno("Report collaboratore", f"PDF creato:\n{pdf_path}\n\nVuoi aprirlo?"):
            open_path(str(pdf_path))
        return pdf_path
    except Exception as exc:
        messagebox.showerror("Report collaboratore", f"Impossibile generare il PDF.\n\n{exc}")
        return None


def _fpcr_list_export_selected(self):
    try:
        collaborator_id = self.selected_collaborator_id()
    except Exception:
        collaborator_id = None
    if collaborator_id is None:
        messagebox.showwarning("Report collaboratore", "Seleziona un collaboratore dall'elenco.")
        return
    _fpcr_generate_collaborator_report_pdf(self.db, collaborator_id, self)


def _fpcr_detail_export(self):
    _fpcr_generate_collaborator_report_pdf(self.db, self.collaborator_id, self)


def _fpcr_dashboard_export(self):
    try:
        collaborator_id = self._selected_collaborator_id()
    except Exception:
        collaborator_id = None
    if not collaborator_id:
        messagebox.showwarning("Report collaboratore", "Seleziona un collaboratore specifico nel filtro. Il report completo e' individuale.")
        return
    _fpcr_generate_collaborator_report_pdf(self.db, collaborator_id, self)


try:
    _FPCR_ORIG_COLLAB_LIST_INIT = CollaboratorListWindow.__init__
    def _fpcr_collab_list_init(self, master, db):
        _FPCR_ORIG_COLLAB_LIST_INIT(self, master, db)
        try:
            top = self.content_frame.winfo_children()[0]
            ttk.Button(top, text="Report collaboratore PDF", command=self.export_collaborator_report_pdf).pack(side="right", padx=(0, 8))
        except Exception:
            try:
                bar = ttk.Frame(self.content_frame, padding=(16, 0, 16, 10))
                bar.pack(fill="x")
                ttk.Button(bar, text="Report collaboratore PDF", command=self.export_collaborator_report_pdf).pack(side="right")
            except Exception:
                pass
    CollaboratorListWindow.__init__ = _fpcr_collab_list_init
    CollaboratorListWindow.export_collaborator_report_pdf = _fpcr_list_export_selected
except Exception:
    pass


try:
    _FPCR_ORIG_COLLAB_DETAIL_INIT = CollaboratorDetailWindow.__init__
    def _fpcr_collab_detail_init(self, master, db, collaborator_id: int, on_changed=None):
        _FPCR_ORIG_COLLAB_DETAIL_INIT(self, master, db, collaborator_id, on_changed=on_changed)
        try:
            ttk.Button(self.header, text="Report collaboratore PDF", command=self.export_collaborator_report_pdf).pack(side="right", padx=(0, 12), pady=12)
        except Exception:
            pass
    CollaboratorDetailWindow.__init__ = _fpcr_collab_detail_init
    CollaboratorDetailWindow.export_collaborator_report_pdf = _fpcr_detail_export
except Exception:
    pass


try:
    Module2DashboardWindow.export_collaborator_report = _fpcr_dashboard_export
except Exception:
    pass

