def _fp_ensure_dir(path: Path) -> Path:
    Path(path).mkdir(parents=True, exist_ok=True)
    return Path(path)


def _fp_integrated_base_dir() -> Path:
    try:
        root = get_app_data_dir()
    except Exception:
        root = Path.home() / "FinancePlus_Integrated_Data"
    return _fp_ensure_dir(Path(root) / "moduli_integrati")


def _fp_materialize_integrated_modules(force: bool = False) -> Path:
    """Scrive su disco i moduli integrati dentro la cartella dati dell'app.

    Il .py resta unico e portabile: al primo avvio rigenera i moduli operativi
    incorporati e li rende eseguibili/importabili senza copiare manualmente cartelle.
    """
    base_dir = _fp_integrated_base_dir()
    manifest = []
    for relative, payload_b64 in _FP_EMBEDDED_MODULES.items():
        target = base_dir / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        data = _fp_gzip.decompress(_fp_base64.b64decode(payload_b64.encode("ascii")))
        if force or not target.exists() or target.read_bytes() != data:
            target.write_bytes(data)
        manifest.append({"file": relative, "path": str(target), "bytes": len(data)})
    try:
        (base_dir / "manifest_moduli_integrati.json").write_text(json.dumps(manifest, indent=2, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass
    if str(base_dir) not in sys.path:
        sys.path.insert(0, str(base_dir))
    return base_dir


def _fp_open_integrated_path(path: Path):
    try:
        open_path(str(path))
    except Exception:
        try:
            open_file_or_folder(path)  # type: ignore[name-defined]
        except Exception:
            if messagebox:
                messagebox.showinfo("Moduli integrati", str(path))


def _fp_launch_integrated_script(script_name: str, args=None, title: str = "Modulo integrato"):
    args = list(args or [])
    base_dir = _fp_materialize_integrated_modules(force=False)
    script_path = base_dir / script_name
    if not script_path.exists():
        messagebox.showerror(title, f"File non trovato dopo l'integrazione:\n{script_path}")
        return
    try:
        _fp_subprocess.Popen([sys.executable, str(script_path), *args], cwd=str(base_dir))
    except Exception as exc:
        messagebox.showerror(title, f"Impossibile avviare il modulo:\n{script_path}\n\n{exc}")


def _fp_finalyst_service():
    base_dir = _fp_materialize_integrated_modules(force=False)
    if str(base_dir) not in sys.path:
        sys.path.insert(0, str(base_dir))
    mod = _fp_importlib.import_module("finalyst_cr_report")
    return mod


def _fp_run_finalyst_report_dialog(parent=None, output_format: str = "pdf"):
    try:
        base_dir = _fp_materialize_integrated_modules(force=False)
        out_dir = _fp_ensure_dir(get_app_data_dir() / "report_finalyst_cr")
        if str(base_dir) not in sys.path:
            sys.path.insert(0, str(base_dir))
        gui_mod = _fp_importlib.import_module("finalyst_cr_report.gui_tk")
        result = gui_mod.run_cr_report_gui(parent=parent, output_dir=str(out_dir), open_after=True, output_format=output_format)
        return result
    except Exception as exc:
        messagebox.showerror("Finalyst CR Report", f"Errore apertura/generazione report {output_format.upper()}:\n\n{exc}")
        return None


def _fp_create_finalyst_template_dialog(parent=None):
    try:
        base_dir = _fp_materialize_integrated_modules(force=False)
        if str(base_dir) not in sys.path:
            sys.path.insert(0, str(base_dir))
        from tkinter import filedialog
        initial = _fp_ensure_dir(get_app_data_dir() / "report_finalyst_cr")
        out = filedialog.asksaveasfilename(
            parent=parent,
            title="Salva modello Excel Centrale Rischi",
            defaultextension=".xlsx",
            initialdir=str(initial),
            initialfile="modello_cr.xlsx",
            filetypes=[("Excel", "*.xlsx")],
        )
        if not out:
            return None
        api_mod = _fp_importlib.import_module("finalyst_cr_report")
        path = api_mod.create_template(out)
        messagebox.showinfo("Finalyst CR Report", f"Modello Excel creato:\n{path}")
        return path
    except Exception as exc:
        messagebox.showerror("Finalyst CR Report", f"Errore creazione modello Excel:\n\n{exc}")
        return None


def _fp_open_integrated_tools_hub(self):
    base_dir = _fp_materialize_integrated_modules(force=False)
    win = tk.Toplevel(self)
    win.title("FinancePlus - Moduli integrati")
    win.geometry("920x620")
    win.configure(bg=BG_COLOR)
    header = tk.Frame(win, bg=PRIMARY_DARK)
    header.pack(fill="x")
    tk.Label(
        header,
        text="Moduli integrati FinancePlus",
        bg=PRIMARY_DARK,
        fg="white",
        font=("Segoe UI", 18, "bold"),
    ).pack(anchor="w", padx=20, pady=(16, 2))
    tk.Label(
        header,
        text="PHANTOM, Rating/MCC, Catalogatore, Finalyst CR PDF/Word e materiali guida sono incorporati in questo unico file .py.",
        bg=PRIMARY_DARK,
        fg="#dbe6ff",
        font=("Segoe UI", 9),
        wraplength=840,
        justify="left",
    ).pack(anchor="w", padx=20, pady=(0, 16))

    body_scroll = ScrollableBody(win)
    body_scroll.pack(fill="both", expand=True)
    body = ttk.Frame(body_scroll.inner, padding=18)
    body.pack(fill="both", expand=True)
    add_logo_badge(body, size=(720, 520), watermark=True, bg=BG_COLOR, relx=0.54, rely=0.52, anchor="center")

    intro = (
        "I pulsanti avviano i moduli materializzati automaticamente nella cartella dati del gestionale. "
        "Finalyst CR lavora direttamente dal gestionale con selezione file Excel/CSV e genera PDF o Word."
    )
    ttk.Label(body, text=intro, wraplength=820, style="SubHeader.TLabel").pack(anchor="w", pady=(0, 14))

    grid = ttk.Frame(body)
    grid.pack(fill="both", expand=True)
    for c in range(2):
        grid.columnconfigure(c, weight=1)

    actions = [
        ("PHANTOM Suite TOP", "Dashboard clienti, documenti, richieste, scoring PHANTOM, CR, Business Plan e PDF.", lambda: _fp_launch_integrated_script("phantom_suite_top.py", title="PHANTOM Suite TOP")),
        ("Finance PLUS Rating/MCC", "Rating bancario simulato, MCC, DSCR, report e template dati.", lambda: _fp_launch_integrated_script("finance_plus_rating_mcc_integrato.py", title="Finance PLUS Rating/MCC")),
        ("Finance PLUS Monolite", "Monolite autosufficiente con catalogatori, rating, MCC, DSCR e simulatore.", lambda: _fp_launch_integrated_script("finance_plus_monolite.py", title="Finance PLUS Monolite")),
        ("Catalogatore documenti", "Import manuale/automatico, email/WhatsApp, OCR, hash duplicati e archivio SQLite.", lambda: _fp_launch_integrated_script("Catalogatore_Doc_Integrato_Unico.py", title="Catalogatore documenti")),
        ("Finalyst CR Report PDF", "Seleziona Excel/CSV CR e genera il report PDF pronto da consegnare.", lambda: _fp_run_finalyst_report_dialog(parent=win, output_format="pdf")),
        ("Finalyst CR Report Word", "Seleziona Excel/CSV CR e genera il report Word .docx modificabile.", lambda: _fp_run_finalyst_report_dialog(parent=win, output_format="docx")),
        ("Crea modello Excel CR", "Genera il modello Excel compilabile per il report Centrale Rischi.", lambda: _fp_create_finalyst_template_dialog(parent=win)),
        ("Apri cartella moduli", "Apre la cartella in cui sono stati estratti moduli, guide e materiali allegati.", lambda: _fp_open_integrated_path(base_dir)),
    ]

    def make_card(parent, title, desc, cmd, row, col):
        card = tk.Frame(parent, bg=CARD_BG, highlightthickness=1, highlightbackground="#d8e1f0")
        card.grid(row=row, column=col, sticky="nsew", padx=8, pady=8)
        tk.Label(card, text=title, bg=CARD_BG, fg=TEXT_COLOR, font=("Segoe UI", 12, "bold"), anchor="w").pack(fill="x", padx=14, pady=(12, 2))
        tk.Label(card, text=desc, bg=CARD_BG, fg=MUTED_TEXT, font=("Segoe UI", 9), wraplength=360, justify="left", anchor="w").pack(fill="x", padx=14, pady=(0, 10))
        tk.Button(card, text="Apri", command=cmd, bg=PRIMARY_COLOR, fg="white", activebackground=PRIMARY_HOVER, activeforeground="white", relief="flat", padx=14, pady=7, cursor="hand2", font=("Segoe UI", 9, "bold")).pack(anchor="w", padx=14, pady=(0, 12))

    for idx, (title, desc, cmd) in enumerate(actions):
        r, c = divmod(idx, 2)
        grid.rowconfigure(r, weight=1)
        make_card(grid, title, desc, cmd, r, c)


def _fp_patch_main_application_integrated_buttons():
    try:
        if getattr(MainApplication, "_fp_integrated_patch_applied", False):
            return
        MainApplication.open_integrated_tools_hub = _fp_open_integrated_tools_hub
        _orig_build_ui = MainApplication._build_ui

        def _patched_build_ui(self):
            _orig_build_ui(self)
            try:
                main_container = self.winfo_children()[0]
                sidebar = main_container.winfo_children()[0]
                tk.Button(
                    sidebar,
                    text="MODULI INTEGRATI",
                    command=self.open_integrated_tools_hub,
                    bg="#B9792E",
                    fg="white",
                    activebackground="#9d6325",
                    activeforeground="white",
                    relief="flat",
                    bd=0,
                    padx=10,
                    pady=8,
                    font=("Segoe UI", 9, "bold"),
                    cursor="hand2",
                    anchor="w",
                ).pack(fill="x", padx=12, pady=(12, 3))
            except Exception:
                pass
        MainApplication._build_ui = _patched_build_ui
        MainApplication._fp_integrated_patch_applied = True
    except Exception:
        pass


_fp_patch_main_application_integrated_buttons()


def _fp_integrated_cli_requested() -> bool:
    args = list(sys.argv[1:])
    if not args:
        return False
    if "--materializza-moduli" in args:
        path = _fp_materialize_integrated_modules(force=True)
        print(path)
        return True
    if "--phantom-suite" in args:
        path = _fp_materialize_integrated_modules(force=False) / "phantom_suite_top.py"
        os.execv(sys.executable, [sys.executable, str(path)] + [a for a in args if a != "--phantom-suite"])
        return True
    if "--financeplus-rating-mcc" in args:
        path = _fp_materialize_integrated_modules(force=False) / "finance_plus_rating_mcc_integrato.py"
        os.execv(sys.executable, [sys.executable, str(path)] + [a for a in args if a != "--financeplus-rating-mcc"])
        return True
    if "--catalogatore-documenti" in args:
        path = _fp_materialize_integrated_modules(force=False) / "Catalogatore_Doc_Integrato_Unico.py"
        os.execv(sys.executable, [sys.executable, str(path)] + [a for a in args if a != "--catalogatore-documenti"])
        return True
    if "--financeplus-monolite" in args:
        path = _fp_materialize_integrated_modules(force=False) / "finance_plus_monolite.py"
        os.execv(sys.executable, [sys.executable, str(path)] + [a for a in args if a != "--financeplus-monolite"])
        return True
    if "--finalyst-template" in args:
        idx = args.index("--finalyst-template")
        out = args[idx + 1] if idx + 1 < len(args) else str(Path.cwd() / "modello_cr.xlsx")
        _fp_materialize_integrated_modules(force=False)
        api_mod = _fp_importlib.import_module("finalyst_cr_report")
        print(api_mod.create_template(out))
        return True
    return False


if _fp_integrated_cli_requested():
    raise SystemExit(0)

