CLEAN_UI_VERSION = "2.1-scroll-logo"


def _clean_fp_row_get(row, key, default=""):
    try:
        if row is None:
            return default
        if hasattr(row, "keys") and key in row.keys():
            value = row[key]
            return default if value is None else value
        if isinstance(row, dict):
            return row.get(key, default)
        return getattr(row, key, default)
    except Exception:
        return default


def _clean_open_integrated_hub(self):
    try:
        if "_fp_open_integrated_tools_hub" in globals():
            return _fp_open_integrated_tools_hub(self)
        messagebox.showwarning("Moduli integrati", "Hub moduli integrati non disponibile in questa build.")
    except Exception as exc:
        messagebox.showerror("Moduli integrati", f"Errore apertura hub moduli integrati:\n\n{exc}")


def _clean_launch_integrated(self, script_name, title, args=None):
    try:
        if "_fp_launch_integrated_script" in globals():
            return _fp_launch_integrated_script(script_name, args=args or [], title=title)
        messagebox.showwarning(title, "Funzione di avvio moduli integrati non disponibile.")
    except Exception as exc:
        messagebox.showerror(title, f"Impossibile avviare il modulo:\n\n{exc}")


