def _clean_open_collaborator_report(self):
    try:
        rows = list(self.db.list_collaborators("") or [])
    except Exception:
        rows = []
    if not rows:
        messagebox.showwarning("Report collaboratore", "Non risultano collaboratori registrati.")
        return

    win = tk.Toplevel(self)
    win.title("Report collaboratore PDF")
    win.geometry("620x360")
    win.configure(bg=BG_COLOR)
    win.transient(self)

    header = tk.Frame(win, bg=PRIMARY_DARK)
    header.pack(fill="x")
    tk.Label(header, text="Report collaboratore PDF", bg=PRIMARY_DARK, fg="white", font=("Segoe UI", 18, "bold")).pack(anchor="w", padx=20, pady=(18, 2))
    tk.Label(header, text="Seleziona un collaboratore e genera una scheda completa stampabile: aziende associate, documenti e richieste.", bg=PRIMARY_DARK, fg="#dbe6ff", font=("Segoe UI", 9), wraplength=560, justify="left").pack(anchor="w", padx=20, pady=(0, 18))

    body_scroll = ScrollableBody(win)
    body_scroll.pack(fill="both", expand=True)
    body = tk.Frame(body_scroll.inner, bg=BG_COLOR)
    body.pack(fill="both", expand=True, padx=22, pady=18)
    add_logo_badge(body, size=(520, 380), watermark=True, bg=BG_COLOR, relx=0.52, rely=0.56, anchor="center")
    tk.Label(body, text="Collaboratore", bg=BG_COLOR, fg=TEXT_COLOR, font=("Segoe UI", 10, "bold")).pack(anchor="w")

    values = []
    by_index = []
    for r in rows:
        cid = int(_clean_fp_row_get(r, "id", 0) or 0)
        nome = str(_clean_fp_row_get(r, "nome", "") or "").strip()
        cognome = str(_clean_fp_row_get(r, "cognome", "") or "").strip()
        mail = str(_clean_fp_row_get(r, "mail", "") or "").strip()
        label = f"{cognome} {nome}".strip() or f"Collaboratore {cid}"
        if mail:
            label += f" - {mail}"
        values.append(label)
        by_index.append(cid)

    var = tk.StringVar(value=values[0] if values else "")
    combo = ttk.Combobox(body, textvariable=var, values=values, state="readonly", width=72)
    combo.pack(fill="x", pady=(6, 18))
    combo.current(0)

    info = tk.Label(body, text="Il PDF viene salvato nella cartella dati/report_collaboratori e puo essere aperto subito.", bg=BG_COLOR, fg=MUTED_TEXT, font=("Segoe UI", 9), justify="left", wraplength=560)
    info.pack(anchor="w", pady=(0, 18))

    btnbar = tk.Frame(body, bg=BG_COLOR)
    btnbar.pack(fill="x")

    def do_generate():
        idx = combo.current()
        if idx < 0 or idx >= len(by_index):
            messagebox.showwarning("Report collaboratore", "Seleziona un collaboratore.")
            return
        if "_fpcr_generate_collaborator_report_pdf" not in globals():
            messagebox.showerror("Report collaboratore", "Generatore PDF collaboratore non disponibile in questa build.")
            return
        _fpcr_generate_collaborator_report_pdf(self.db, by_index[idx], win)

    tk.Button(btnbar, text="Genera PDF", command=do_generate, bg=PRIMARY_COLOR, fg="white", activebackground=PRIMARY_HOVER, activeforeground="white", relief="flat", padx=18, pady=9, cursor="hand2", font=("Segoe UI", 10, "bold")).pack(side="left")
    tk.Button(btnbar, text="Chiudi", command=win.destroy, bg="#e5e7eb", fg=TEXT_COLOR, activebackground="#d1d5db", relief="flat", padx=18, pady=9, cursor="hand2", font=("Segoe UI", 10, "bold")).pack(side="left", padx=(10, 0))


