def _clean_action_card(parent, title, subtitle, command, *, row, col, color=None, big=False):
    card = tk.Frame(parent, bg=CARD_BG, highlightthickness=1, highlightbackground="#d9e2ef")
    card.grid(row=row, column=col, sticky="nsew", padx=9, pady=9)
    card.grid_propagate(False)
    h = 158 if big else 132
    card.configure(height=h)

    band = tk.Frame(card, bg=color or PRIMARY_COLOR, width=8)
    band.pack(side="left", fill="y")
    inner = tk.Frame(card, bg=CARD_BG)
    inner.pack(side="left", fill="both", expand=True, padx=14, pady=12)
    tk.Label(inner, text=title, bg=CARD_BG, fg=TEXT_COLOR, font=("Segoe UI", 12 if big else 10, "bold"), justify="left", anchor="w", wraplength=260).pack(anchor="w")
    tk.Label(inner, text=subtitle, bg=CARD_BG, fg=MUTED_TEXT, font=("Segoe UI", 9), justify="left", anchor="w", wraplength=290).pack(anchor="w", pady=(5, 10))
    tk.Button(inner, text="Apri", command=command, bg=color or PRIMARY_COLOR, fg="white", activebackground=PRIMARY_HOVER, activeforeground="white", relief="flat", padx=16, pady=6, cursor="hand2", font=("Segoe UI", 9, "bold")).pack(anchor="w")
    return card


def _clean_build_ui(self):
    # Pulizia totale della vecchia dashboard per eliminare doppioni visibili.
    for child in list(self.winfo_children()):
        try:
            child.destroy()
        except Exception:
            pass

    main = tk.Frame(self, bg=BG_COLOR)
    main.pack(fill="both", expand=True)

    sidebar_shell = tk.Frame(main, bg=PRIMARY_DARK, width=302)
    sidebar_shell.pack(side="left", fill="y")
    sidebar_shell.pack_propagate(False)
    sidebar_shell.rowconfigure(0, weight=1)
    sidebar_shell.columnconfigure(0, weight=1)

    sidebar_canvas = tk.Canvas(sidebar_shell, bg=PRIMARY_DARK, highlightthickness=0)
    sidebar_vbar = ttk.Scrollbar(sidebar_shell, orient="vertical", command=sidebar_canvas.yview, style="Visible.Vertical.TScrollbar")
    sidebar_hbar = ttk.Scrollbar(sidebar_shell, orient="horizontal", command=sidebar_canvas.xview, style="Visible.Horizontal.TScrollbar")
    sidebar_canvas.configure(yscrollcommand=sidebar_vbar.set, xscrollcommand=sidebar_hbar.set)
    sidebar_canvas.grid(row=0, column=0, sticky="nsew")
    sidebar_vbar.grid(row=0, column=1, sticky="ns")
    sidebar_hbar.grid(row=1, column=0, sticky="ew")

    sidebar = tk.Frame(sidebar_canvas, bg=PRIMARY_DARK)
    sidebar_window = sidebar_canvas.create_window((0, 0), window=sidebar, anchor="nw")

    def _sync_sidebar_scroll(_event=None):
        sidebar_canvas.configure(scrollregion=sidebar_canvas.bbox("all"))

    def _sync_sidebar_width(event):
        sidebar_canvas.itemconfigure(sidebar_window, width=max(event.width, sidebar.winfo_reqwidth()))
        _sync_sidebar_scroll()

    sidebar.bind("<Configure>", _sync_sidebar_scroll)
    sidebar_canvas.bind("<Configure>", _sync_sidebar_width)
    bind_mousewheel_to_canvas(sidebar_canvas, sidebar_shell, ignore_native_scroll_children=False)
